INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (986, 'A head and shoulders portrait of a woman with a green face shows her with the shadow of her woman&#x2019;s hat over her face painted in a swoop of emerald green.', 986, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (987, 'Matisse made literal translations of what his eye saw, so that if a shadow looked greenish, he painted it green, and if an edge could be made by not painting the canvas, he left it bare.', 987, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (988, 'For example, another painting depicts a goldfish in a bowl on a table by a French window opening onto a tiny balcony.', 988, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (989, 'The window and room are boldly outlined in black; the goldfish bowl and much else is half painted.', 989, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (990, 'The Red Studio is a daring work, showing the furniture and objects in his studio outlined in white (made simply by leaving the canvas white where he wanted the line to be) and some colour, with minimal perspective, resulting in a painting that is a red square of canvas with objects, and some architectural elements such as a pair of shutters floating on it.', 990, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (991, 'Matisse also made a number of bronze casts, the best known of which is the triptych The Back, an abstracted human torso viewed from the back, carved in relief as semi cylindrical shapes to represent the two sides of the back and the buttocks, leaving a space in the middle to represent the division caused by the spine.', 991, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (992, 'The sculptures were commissioned for a specific interior and were thus made as three bronze wall reliefs.', 992, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (993, 'At the turn of the century, the influence of photography on painting was clear.', 993, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (994, 'It was also having an effect on sculpture.', 994, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (995, 'This period saw some of the greatest sculptors emerge, leaving behind the tradition of copying classical sculpture and measuring from life.', 995, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (996, 'EARLY TWENTIETH CENTURY SCULPTURE', 996, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (997, 'Auguste Rodin', 997, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (998, 'Rodin, a French artist who is considered to be one of the greatest modern sculptors, made his best known works at the turn of the century.', 998, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (999, 'Two of these, The Kiss (1901) and The Thinker are known all over the world.', 999, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1000, 'Rodin&#x2019;s achievement was to use traditional stone and bronze cast sculpture techniques to represent movement, and to draw attention to the physical material property of the sculpture as a block of stone.', 1000, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1001, 'Rodin did not want to make sculpture that looked lifelike but was closer to the impressionists and cubists in his desire to acknowledge surface and material as an important part of the work for its own sake.', 1001, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1002, 'Rodin saw the plinth as an integral part of the sculpture to be acknowledged rather than seen as an unfortunate necessity, again drawing attention to the sculpture as an object rather than something that should try to replicate reality.', 1002, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1003, 'He often left parts of the plinth unfinished or made his figures emerge from the stone of the plinth.', 1003, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1004, 'Although Rodin was able to carve and model the human form with great accuracy he often exaggerated proportions to enhance the impression he wanted a particular work to make, using the tricks of classical sculpture such as perspective and foreshortening.', 1004, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1005, 'This can be seen very clearly in The Kiss, a white marble sculpture that shows a seated male and female nude entwined in a kiss.', 1005, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1006, 'The figures are about one and a half times larger than life, their bodies are carved without excess of detail, and the feet and legs are exaggerated.', 1006, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1007, 'The couple grow out of the stone block on which they sit which is left roughly carved.', 1007, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1008, 'The Kiss has become a world famous representation of romantic and sexual love.', 1008, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1009, 'Rodin made several copies and a number of smaller bronze versions.', 1009, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1010, 'There is a similar bronze of a girl lying on a low plinth, her body at points disappearing into the plinth as though it has not yet been formed.', 1010, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1011, 'In this work Rodin wanted to express the state of sleep.', 1011, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1012, 'Rodin&#x2019;s Thinker is an iconic work, a slightly larger than life size seated male nude with one elbow on a knee, the hand made into a fist on which the bent forward head rests.', 1012, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1013, 'The sculpture is made in bronze, with a very dark almost black patina and the modelling is relatively rough.', 1013, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1014, 'It grows out of a plinth about one metre high, raising the seated figure to the standing viewer&#x2019;s eye level.', 1014, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1015, 'The Thinker is a representation of existential angst, and gained its reputation by succeeding in the three dimensional representation of a state of mind.', 1015, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1016, 'It is frequently reproduced, used in advertising or merely invoked in conversation by mimicking the physical gesture made by the figure.', 1016, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1017, 'This quotation of Rodin&#x2019;s pose is both a reference to the actual sculpture and more generally to illustrate the idea of intense thought.', 1017, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1018, 'Walking Man is Rodin&#x2019;s solution to another challenge &#x2013; how to represent motion in figurative sculpture.', 1018, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1019, 'This is a life size dark brown bronze sculpture of a naked striding man who that on the floor on a minimal plinth so that the viewer is on the same level.', 1019, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1020, 'Rodin made public commissions, the best known of which is The Burghers of Calais, which shows an event in French history in which the civic leaders of the town of Calais were imprisoned.', 1020, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1021, 'Rodin&#x2019;s sculpture shows them chained together, standing front to back and forming a melancholy circle, which draws the viewer to it.', 1021, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1022, 'The sculpture itself forms a cage made by the bronze circle of figures.', 1022, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1023, 'A statue of the French writer Balzac is a radical departure from contemporary portraiture &#x2013; Balzac is shown standing, wrapped in a floor length cloak so that only his head is visible.', 1023, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1024, 'He has wild hair and a fierce expression and the figure leans back at an almost unrealistic angle.', 1024, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1025, 'A commission for a pair of monumental bronze gates for a public building in Paris resulted in The Gates of Hell, a bronze relief that occupied Rodin for years.', 1025, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1026, 'It is a densely modelled depiction of purgatory covered with figures, for which Rodin did a large number of sketches and studies in bronze.', 1026, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1027, 'Constantin Brancusi', 1027, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1028, 'Another artist who considered the plinth to be a part of the sculpture was Brancusi, who lived and worked in Paris at the end of the 19th century.', 1028, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1029, 'Brancusi&#x2019;s works were often no more than elaborated plinth shapes, with simple forms placed on them made in plaster, bronze, wood and marble.', 1029, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1030, 'One of his best known works is Endless Column, a polished bronze column on a wooden plinth made of truncated three dimensional diamond shapes placed one on top of the other, about 10 metres high.', 1030, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1031, 'He also made a small carved head of a sleeping person which is so smooth and almost featureless as to almost appear to be a large stone.', 1031, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1032, 'Alberto Giacommetti', 1032, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1033, 'In contrast Italian artist Giacommetti had little interest in the plinth.', 1033, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1034, 'Giacommetti&#x2019;s bronze sculptures are extremely elongated usually standing figures, sometimes single figures, sometimes pairs or groups which often imply movement, or seem to be about to walk.', 1034, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1035, 'They are solitary and isolated figures, reduced to essences of the human form.', 1035, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1036, 'The sculptures are not more than human height and often much smaller, the heads are tiny, the legs and arms no more than rods of metal, the bodies agglomerations of bronze that seem to serve merely to join the limbs, not much more than 30 cm wide.', 1036, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1037, 'The sculptures are modelled roughly so that the metal looks as if it has been dripped, dragged and pinched.', 1037, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1038, 'Giacommetti made a large number of working drawings.', 1038, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1039, 'Gaudier Henri Brzeska', 1039, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1040, 'Gaudier Brzeska made stone and bronze sculptures, mostly small and medium sized, for example a small dark stone carving of a curled up sleeping fawn.', 1040, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1041, 'For the first time artists were entirely free to make whatever they wanted, the only constraint being financial.', 1041, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1042, 'Photography began to be seen as part of an artist&#x2019;s practise, abstraction was on the horizon, and the old traditions ceased to hold sway.', 1042, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1043, 'Several major movements carried art into the twentieth century and the period known as modernism.', 1043, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1044, 'These are surrealism, futurism and dada.', 1044, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1045, 'SURREALISM', 1045, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1046, 'Surrealist art was made in the context of the publishing of Freud&#x2019;s work on the subconscious and of the liberation of art from straightforward narrative or representation of the world.', 1046, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1047, 'The subconscious mind offered new worlds to explore.', 1047, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1048, 'Salvador Dali', 1048, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1049, 'This Spanish artist, born in 1900, is with Magritte the most famous of the surrealists and a candidate for best known artist in the world.', 1049, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1050, 'Dali&#x2019;s paintings or even details of his paintings are instantly recognisable such as the melted clocks which from a small part of one painting but which are instantly associated with Dali and surrealism.', 1050, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1051, 'Dali&#x2019;s surrealism is fantastical, he created dreamlike landscapes filled with distorted objects, nightmarish scenes and apocalyptic wastelands and religious iconography.', 1051, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1052, 'One painting shows mutant human bones that seem to have a life of their own in a grey green no man&#x2019;s land, the aftermath of a war.', 1052, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1053, 'Another shows the crucifixion from Christ&#x2019;s point of view, showing what he would have seen looking down from the cross, the whole image a luridly coloured hallucination.', 1053, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1054, 'A landscape with dead trees has clock faces draped on the trees and on the ground apparently melting and dripping.', 1054, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1055, 'A giant red rose floats in the air above a desert.', 1055, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1056, 'A telephone receiver is replaced by a lobster.', 1056, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1057, 'Where Dali&#x2019;s use of obvious symbolism and his lurid hallucinatory images have made him enduringly popular, his personal eccentricity has only increased his popularity and is difficult to separate from his work.', 1057, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1058, 'Dali dressed as a dandy, often wearing white and sporting a very long waxed moustache that extended beyond his face and pointed up.', 1058, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1059, 'He lived with his wife Galia in a house in Spain at Figuera da Foz where the couple were host to many of their contemporaries.', 1059, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1060, 'Dali is not considered to be the intellectual force behind surrealism, however well known his work has become.', 1060, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1061, 'This role is given to Breton.', 1061, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1062, 'Andre Breton', 1062, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1063, 'The most outspoken member and leader of the surrealists in Paris at the beginning of the twentieth century, Breton made paintings and sculpture, and wrote the Surrealist manifesto that set out to define a new kind of art for new times.', 1063, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1064, 'His best known work is a clothes iron with spikes set into the sole plate.', 1064, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1065, 'Rene Magritte', 1065, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1066, 'Magritte is the most famous of the Surrealists, and indeed is one of the best known artists in the world.', 1066, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1067, 'A French painter born in 1850, Magritte&#x2019;s images are instantly recognisable and attributable, and have been much copied.', 1067, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1068, 'They have influenced advertising imagery for several decades and continue to do so.', 1068, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1069, 'Magritte was interested in both visual and textual puns, for example, &#x2018;Ceci n&#x2019;est pas une pipe&#x2019; (this is not a pipe) is inscribed on a painting of a pipe.', 1069, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1070, 'Many of his paintings feature both words and objects and often the objects are apparently named but the names do not make sense.', 1070, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1071, 'In this way Magritte&apos;s text paintings are both object and subject in the sense that are what they are but the viewer is then told that they are not, leading them to a new consideration of what they are seeing and of what art might do.', 1071, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1072, 'Many of Magritte&apos;s paintings are very well known: a train emerging from a fireplace; an apple obscuring most of the front of a bowler hatted man&#x2019;s face; an inverted mermaid with a fish&#x2019;s head and woman&#x2019;s legs and pelvis; an easel by a window with a painting on it, the painting showing the view through the window; two grey spaceship like objects titled Floating Spheres; and a man&#x2019;s face which is also a female torso in which the pubic hair is also the man&#x2019;s beard.', 1072, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1073, 'These are painted in a highly realistic but flat and stiff style, with a muted palette, smooth, flat and few brushstrokes.', 1073, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1074, 'The ludicrous juxtapositions of objects and people are nonetheless poetic and leave the viewer hoping that they might actually happen, that the everyday might mix up and become magical, in other words, surreal.', 1074, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1075, 'Man Ray', 1075, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1076, 'A French surrealist sculptor, painter and photographer working in Paris in the early twentieth century, Man Ray experimented with photography to create unique images, using various methods including placing objects on light sensitive plates and then exposing them to get an image.', 1076, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1077, 'Man Ray took a well known photograph of Duchamp with a star shaved out of the back of his head smoking a pipe.', 1077, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1078, 'Meret Oppenheim', 1078, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1079, 'Oppenheim made a sculpture of a fur covered cup, saucer and spoon, as well as one of a pair of white high heeled shoes upside down on a silver salver trussed with string and paper frills on the ends of the heels.', 1079, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1080, 'She also made a pair of leather gloves, the conventional stitched ridges on the backs of each made to resemble the veins on the back of a hand.', 1080, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1081, 'Hans Bellmer', 1081, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1082, 'Bellmer made photographs of dolls and parts of dolls arranged in tableaux, as well as sculptures.', 1082, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1083, 'His work deals with sexual taboo.', 1083, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1084, 'Lazlo Moholy Nagy', 1084, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1085, 'This Hungarian artist was a contemporary of the surrealists and is best known for a number of pioneering semi abstract films and photographs using architectural form, light and shade.', 1085, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1086, 'Surrealism provided the context for an avant garde group of artists, performers and writers to produce work that they collectively titled Dada.', 1086, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1087, 'DADA', 1087, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1088, 'The dada artists were based in Berlin but drawn from a number of different nationalities.', 1088, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1089, 'They worked in all media and also made performance and musical work, performing regularly under the name Cabaret Voltaire.', 1089, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1090, 'The name comes is a combination of a French word for hobby horse but was intended to have no specific meaning.', 1090, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1091, 'Marcel Duchamp', 1091, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1092, 'Known in the twentieth century as the father of conceptualism, the French artist Marcel Duchamp was among the artists escaping Europe for America to avoid censorship and persecution as Jews.', 1092, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1093, 'He founded Dada and became notorious for his controversial and usually sculptural works, in particular the ones that became known as ready mades.', 1093, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1094, 'The notorious Fountain, exhibited at the Armoury show in New York in 1913 was in fact a gents&#x2019; ceramic urinal placed on its sided so that it could be said to have the shape of a Buddha or a wall fountain.', 1094, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1095, 'Duchamp signed the urinal on the front, R.', 1095, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1096, 'Mutt, (one of the invented punning names that Duchamp used to sign his work).', 1096, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1097, 'Fountain created a furore because it was a bought object, to which nothing had been added, that Duchamp claimed to make into a work of art merely by the act of signing it and proclaiming authorship.', 1097, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1098, 'The radical step taken by Duchamp with his ready mades, a cycle wheel attached to the seat of a stool for example or a metal bottle dryer, was to have far reaching implications for art.', 1098, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1099, 'Duchamp employed pseudonyms and puns as part of his work.', 1099, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1100, 'He created a female alter ego, Rrose Selavy (a pun on &#x2018;C&#x2019;est la vie&#x2019;), who authenticated and signed many of his works including the urinal.', 1100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1101, 'He photographed himself dressed as Rrose, a rather unconvincing manifestation.', 1101, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1102, 'Rrose produced a perfume named La Belle Haleine, literally &#x2018;beautiful breath&#x2019;, intended as an allusion to its opposite, bad breath, and a pun on &#x2018;La belle Helene&#x2019;, Helen of troy.', 1102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1103, 'Inframince or infrathin was a concept involving the declaration of an invisible or intangible and banal act or action to be a work of art.', 1103, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1104, 'For example the static friction and the sound of velvet trouser legs rubbing together and the warmth left on a recently vacated seat.', 1104, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1105, 'Almost as notorious as Fountain was Duchamp&#x2019;s defaced reproduction of the Mona Lisa.', 1105, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1106, 'Making a pun on the letters LHGC which appear below the face of the Mona Lisa he wrote that &#x2018;elle a un grand cou&#x2019; which translates as &#x2018;she has a fat arse&#x2019; and drew a moustache on her face.', 1106, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1107, 'This re appropriated image became one of the best known images in twentieth century art.', 1107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1108, 'Duchamp made a number of bronze and wax sculptures which were casts of male and female sexual parts, taking, for example, a mould from female genitals which gave him a negative from which he cast in bronze rather than make a positive from it.', 1108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1109, 'One of Duchamp&apos;s last works was L&#x2019;Origin du Monde, a large peepshow containing a wax female torso, laid on an apparent mossy bank, the head out of view, with the genitals exposed.', 1109, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1110, 'There is a drawing by Courbet of a nude in a similar pose.', 1110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1111, 'The apparently innocent tableau with its celebratory title became due to the voyeuristic way in which the viewer was required to look at it tainted with an atmosphere of illicit pleasure, abuse or even murder.', 1111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1112, 'The Large Glass, also known as The Bride Stripped Bare by her Bachelors Even, is a large sculpture comprising a screen print onto two pieces of glass held in a metal freestanding frame which was made in an edition.', 1112, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1113, 'This is Duchamp&#x2019;s least understood work and it has always resisted interpretation.', 1113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1114, 'The images printed on the glass are geometric rays, lines and a coffee grinder with three buckets that was a motif Duchamp repeatedly returned to and had made several drawings of.', 1114, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1115, 'The buckets on the grinder are sometimes supposed to represent the bachelors, but in general the meaning of the work remains opaque.', 1115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1116, 'Duchamp also made several paintings of the coffee grinder that appears in the Large Glass.', 1116, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1117, 'Duchamp was photographed by Man Ray with a star shaved out of the back of his close cut hair.', 1117, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1118, 'He played chess every day of his life.', 1118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1119, 'Kurt Schwitters', 1119, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1120, 'Schwitters, a leading Dada artist and poet, invented the concept of Merz, a way of working and making art that he applied to everything he did.', 1120, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1121, 'The most significant manifestation of this is the Merzbau, the interior of a house of which he transformed in its entirety by constructing organic and crystalline protrusions and projections from timber, wire, plaster and papier mach&#xe9;.', 1121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1122, 'The rooms became like white caves or cubist grottos.', 1122, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1123, 'Schwitters also made the (unfinished) Merzbarn during the time he spent in the Lake District in England, a small stone cottage that he transformed with cement and plaster reliefs.', 1123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1124, 'Schwitters began his career as a graphic designer and typographer and produced innovative work using unusual combinations of typefaces.', 1124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1125, 'He developed an interest in type as a visual form and much of his later work incorporates type in the form of cut out and collaged letters and drawn text.', 1125, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1126, 'Schwitters wrote poetry, which he performed at Dada performances and at Cabaret Voltaire.', 1126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1127, 'His tone poems consisted mainly of sound rather than words.', 1127, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1128, 'The best known is titled Caravane, which Schwitters intoned through a megaphone.', 1128, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1129, 'He regarded his poems as aural images.', 1129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1130, 'Schweitzer&#x2019;s small collages are made from coloured paper, printed paper, cut out printed letters, found images, drawing, paint and other materials.', 1130, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1131, 'He made a great number of these, mostly postcard sized which just predate Braque&#x2019;s and Gris&#x2019;s use of collaged text as part of an image.', 1131, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1132, 'Schwitters also made three dimensional objects, reliefs and assemblages from found materials, timber, wire and paint.', 1132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1133, 'Johannes Baader', 1133, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1134, 'Baader was a German artist involved in Dada and Cabaret Voltaire performances.', 1134, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1135, 'Baader also worked on his own and carried out a number of extreme public performances, often involving physical risk to himself.', 1135, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1136, 'He made a lot of pamphlets and distributed them in mass public leafleting actions for which he was frequently arrested.', 1136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1137, 'Hugo Ball', 1137, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1138, 'Ball was a leading Dada performance artist and a prominent member of Cabaret Voltaire, instigating many of the collaborative performances and writing many of the poems and scripts for them.', 1138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1139, 'Luigi Russolo', 1139, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1140, 'The Art of Noise, Russolo&#x2019;s orchestra, played at many Cabaret Voltaire performances.', 1140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1141, 'Russolo was an experimental musician and composer; there were no conventional instruments in his orchestra, which consisted of household appliances and especially made instruments often producing a deliberate cacophony.', 1141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1142, 'Italy produced an avant garde at the turn of the century which bears comparison with Dada but had entirely different stated aims.', 1142, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1143, 'There had been no Italian surrealism but de Chirico&#x2019;s painting presented a reflexive view of Italian culture and civic life.', 1143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1144, 'Giorgio De Chirico', 1144, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1145, 'The towns and architecture depicted in de Chirico&#x2019;s work are very distinctive for their deserted atmosphere, as if time stands still and the buildings cast long shadows in a strong sunny light.', 1145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1146, 'One painting of an empty town square has a statue of an unspecified man, a tower and an arched arcade or cloister.', 1146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1147, 'The shadows cast by the buildings and statue on the yellow ochre ground and under the arcade are black.', 1147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1148, 'Another painting has the fallen head of a classical marble statue, very like Michelangelo&#x2019;s David, seen lying on its side on the ground, with a broken off hand in the background, offering a critique of Italy&#x2019;s reliance on the culture of its past rather than of the present.', 1148, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1149, 'FUTURISM', 1149, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1150, 'In this environment of stultification and Mussolini&#x2019;s dictatorship, the Futurists, who were based in Milan, wrote a manifesto declaring that speed was their god and that the Future was the only thing worth making art about.', 1150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1151, 'They were reflecting the times, in a period when manufacturing design was changing rapidly, people and news could travel fast, and moving pictures were available to entertain everyone.', 1151, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1152, 'Frederico Marinetti', 1152, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1153, 'The leading member of the Italian Futurist movement, Marinetti was an eccentric didactic who produced many paintings and published texts include several versions of the Futurist Manifesto.', 1153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1154, 'He wrote a Futurist Cookbook, in which he declared pasta to be the most important (and futurist) of all food.', 1154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1155, 'The book contains many edible recipes including several for pasta, but also some very inedible and often ironic ones involving rose petals and entirely green banquets, for example, with complicated presentation methods.', 1155, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1156, 'It offers a glimpse into the surprising romanticism of the futuristic movement.', 1156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1157, 'Marinetti made several performance works including one in which a set of dining chairs were made to dance on and off the stage.', 1157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1158, 'Giacomo Balla', 1158, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1159, 'Balla pursued an obsession with speed in his paintings, trying to find the ultimate way to depict people, animals and objects in motion.', 1159, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1160, 'A portrait of a dachshund walking with spoke like lines emanating from each of its legs is one example.', 1160, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1161, 'Umberto Boccioni', 1161, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1162, 'Boccioni is considered to be the best futurist painter and sculptor, much of his work dealing with how to represent speed in two or three dimensions.', 1162, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1163, 'A bronze sculpture about one metre high called simply &#x2018;Speed&#x2019; depicts a striding man, with apparently aerodynamic fin like structures representing trails of movement leading backwards from his limbs and the back of his head.', 1163, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1164, 'The streamlined helmet shape of his head and the armour like fins give the sculpture a sinister warrior like quality.', 1164, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1165, 'Boccioni made a head of Mussolini by drawing a profile copied from a photograph and using this as a guide to a piece of wood.', 1165, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1166, 'The result is a solid object which has the shape of a vase but the unmistakeable profile of a man from whichever angle it is regarded.', 1166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1167, 'He also made many paintings of his native Milan usually with lines radiating to represent movement of people and vehicles.', 1167, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1168, 'Frances Picabia', 1168, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1169, 'Picabia&#x2019;s work did not follow Futurist prescription but he did have an interest in technological development.', 1169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1170, 'Picabia&#x2019;s work does not fit into any movement but he was very influential and is best known for paintings that depict human machine like figures, abstract paintings and his use of text.', 1170, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1171, 'Picabia also worked as a graphic designer and designed typefaces.', 1171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1172, 'Tamara de Lempicka', 1172, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1173, 'In France, Lempicka painted the newly liberated women of the time.', 1173, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1174, 'Lempicka appears in her own work, distinctive for her straight bobbed hair with low fringe and fashionable clothes.', 1174, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1175, 'In the early twentieth century many artists made work that depicted a futuristic world, either utopian or dystopian.', 1175, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1176, 'Some reflected on the increasingly urban, industrialised way of life.', 1176, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1177, 'Fernand L&#xe9;ger', 1177, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1178, 'L&#xe9;ger, a French painter, had a distinctive style, painting figures as if their bodies were composed of tubular elements, in shaded greys on a whiter ground with occasional additions of primary colours.', 1178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1179, 'L&#xe9;ger&#x2019;s figures look like metal puppets or robots.', 1179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1180, 'Other artists concentrated on the traditional forms of portraiture and still life.', 1180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1181, 'Ernesto Modigliani', 1181, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1182, 'The name Modigliani is always associated with a certain type of portrait, typically of a seated woman with an elongated body and stylised face.', 1182, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1183, 'Modigliani&apos;s portraits are contemplative and painted in a sombre palette with black outlines.', 1183, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1184, 'Giorgio Morandi', 1184, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1185, 'Most of Morandi&#x2019;s still life paintings depict the simplified forms of domestic objects such as jugs, bottles and vases on plain coloured grounds.', 1185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1186, 'Nicholas De Stael', 1186, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1187, 'De Stael also painted simple still lifes using flat bright colours.', 1187, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1188, 'EARLY PHOTOGRAPHY', 1188, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1189, 'The work of American photographers in the first few decades of the twentieth century was very influential.', 1189, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1190, 'They recorded both the social conditions of the depression and the opening up of the vast landscapes of the west.', 1190, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1191, 'Among them were Edward Weston and William Egglestone who photographed city life.', 1191, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1192, 'Walker Evans', 1192, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1193, 'Evans took photographs of rural America during the thirties Depression that showed the extreme poverty and suffering of ordinary people.', 1193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1194, 'Ansel Adams', 1194, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1195, 'Adams was a pioneer of landscape photography known chiefly for his images of American national parks and wildernesses, such as Yosemite and Yellowstone.', 1195, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1196, 'When he made these photographs the wildernesses were not well explored and many parts were remote and inaccessible, necessitating many days trekking with equipment to get the images he wanted.', 1196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1197, 'The photographs capture the enormity and grandiosity of the landscape and came to represent the American wilderness to the rest of the world.', 1197, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1198, 'Because of their huge scope and precise depth of field they seem to be photographic records of time passing, although of course they only record a moment in time.', 1198, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1199, 'An example is a photograph of the central valley in Yosemite which shows a huge waterfall cascading down the opposite side of the valley.', 1199, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1200, 'In Europe, photographers like Eugene Atget and Bill Brandt were recording events, and Brassai was beginning to make abstract images.', 1200, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1201, 'Andresz Kertesz', 1201, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1202, 'The Eastern European photographer Kertesz made images that became instantly familiar, including one of the Arc de Triomphe in Paris.', 1202, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1203, 'Seen from a bird&#x2019;s eye view there is snow on the road surface and the tracks of the few vehicles on the streets have inscribed black parabolas around the arch on the white ground.', 1203, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1204, 'Claude Cahun', 1204, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1205, 'Cahun was a French photographer who made a number of self portraits in which she is dressed as a man without disguising her sexual identity.', 1205, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1206, 'THE MOVING IMAGE', 1206, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1207, 'Artists were trying to represent movement in different ways.', 1207, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1208, 'The Futurists wanted to represent speed and Rodin to create a sculpture of the human form that conveyed movement.', 1208, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1209, 'The invention of moving pictures was less of an early influence on them than the work of one photographer.', 1209, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1210, 'Eadweard Muybridge', 1210, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1211, 'At the turn of the century, Muybridge, an American photographer, made a series of photographs of a horse and a man in motion.', 1211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1212, 'He took a series of exposures at close intervals, producing an image for every second of movement.', 1212, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1213, 'The resulting images had a great influence on artists.', 1213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1214, 'Muybridge&apos;s sequential exposures showed a specific action, for example the components of the movement of a naked walking man and of a galloping horse.', 1214, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1215, 'In the days before moving pictures, no one had foreseen that movement could be represented photographically, reduced to a sequence of still images, nor had they been able to study movement.', 1215, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1216, 'Design and architecture were changing rapidly in Europe and America as a new style emerged, known as International Modernism.', 1216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1217, 'This was a sleek, unadorned way of building championed by Le Corbusier among others.', 1217, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1218, 'Modernist architects were, like the futurists, enthusiastic about the future, proclaiming that in the future everybody would have a home of their own, a modular unit or machine for living in.', 1218, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1219, 'Design schools were established to train a new breed of architects and designers.', 1219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1220, 'The Bauhaus and De Stijl are the best known.', 1220, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1221, 'THE BAUHAUS', 1221, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1222, 'The Bauhaus was in Berlin and was a multi disciplinary school with a distinct ethos.', 1222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1223, 'Students studied across all areas, including theatre design, textiles, ceramics and graphics, as well as architecture and industrial design.', 1223, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1224, 'Some Bauhaus students went on to become artists.', 1224, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1225, 'Oskar Schlemmer', 1225, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1226, 'Schlemmer studied at the Bauhaus as a theatre designer and he made a number of sculptural designs for the Bauhaus productions, later becoming an artist.', 1226, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1227, 'De Stijl was the Dutch design school at which Gerrit Reitveld, the designer of the famous Red Blue Yellow chair, studied.', 1227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1228, 'The influence of the painter Mondrian and Russian constructivism can clearly be seen in De Stijl design.', 1228, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1229, 'Piet Mondrian', 1229, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1230, 'Mondrian was a Dutch artist who began by painting his local countryside, trees and canals before abstracting these scenes and simplifying his palette.', 1230, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1231, 'Mondrian also experimented with canvas shape, making a series of abstract works on oval canvases that were based on trees in a snowy landscape.', 1231, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1232, 'These were conveyed as geometric grey and brown marks on a white ground and C&#xe9;zanne was influenced by them.', 1232, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1233, 'Mondrian made a series of works on small square canvases painted on a white ground, dividing the canvas into irregular blocks with black horizontal and vertical lines and colouring in some of the resulting squares and rectangles with red, yellow and blue.', 1233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1234, 'These works are amongst the most famous abstract paintings in the world.', 1234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1235, 'Later Mondrian began to paint patterns using smaller units and areas, for example Who&#x2019;s Afraid of Red, Yellow and Blue? in 1910, and one titled Subway, which are an homage to the architecture and the new jazz scene of New York.', 1235, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1236, 'Mondrian&apos;s abstract geometric compositions owe something to contemporary Russian constructivists but are significant for their abstraction of landscape into pure geometric form.', 1236, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1237, 'CONSTRUCTIVISM', 1237, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1238, 'In Russia, artists began to make paintings and sculpture that were based on architectural form.', 1238, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1239, 'This was a reaction to the prevailing socialist realist art sponsored by the state, which often amounted to little more than Soviet propaganda.', 1239, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1240, 'Art served the state by representing rural agricultural life as idyllic but productive, and portrayed the worker as the hero of the day.', 1240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1241, 'Artists rebelled by finding a way of working that was entirely different, and most importantly, abstract.', 1241, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1242, 'Vladimir Tatlin made his spiral staircase monument.', 1242, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1243, 'Constructivism used geometry, sharp edged straight lines and primary colours, and the artists laid down the principles on which works could be made.', 1243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1244, 'It had a great influence on contemporary graphic design and typography, and continued to do so throughout the twentieth century.', 1244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1245, 'Constructivism was later taken up by Europeans such as the French painter Victor Vasarely.', 1245, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1246, 'SUPREMATISM', 1246, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1247, 'Kasimir Malevich', 1247, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1248, 'A Russian artist called Malevich developed a form of constructivism that he named suprematism and made primary coloured paintings on white grounds.', 1248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1249, 'He painted the famous Black Square in 1910.', 1249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1250, 'This work was the logical if daring conclusion of his systematic attention to constructivist principles and is often attributed with marking the beginning of abstraction.', 1250, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1251, 'It is also a stark political statement that there is nothing left to paint.', 1251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1252, 'Black square is simply a square canvas painted black all over.', 1252, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1253, 'Square canvases were very unusual since they did not lend themselves well to the composition of traditional subjects of painting, landscapes and portraits.', 1253, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1254, 'The square drew attention to the work itself, not the subject of the work, so that the painting became an object about painting rather than a depiction of something became important.', 1254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1255, 'Mondrian soon began to use the square format.', 1255, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1256, 'Malevich&apos;s painting was entirely black which drew attention to the only possible details of his work, the colour of the black and the brushstrokes.', 1256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1257, 'The viewer was directed to regard only the physicality of the paint in this work.', 1257, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1258, 'This may have been more than Malevich intended.', 1258, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1259, 'Wassily Kandinsky', 1259, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1260, 'Another Russian artist, Kandinsky, is also credited with making some of the first abstract paintings.', 1260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1261, 'Whereas Malevich had made a minimal painting, Kandinsky used bright colours and black on a white ground to make expressive gestural flowing marks, giving rise to the term abstract expressionism.', 1261, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1262, 'He was interested in the relation of music to sound and some of his paintings are attempts to &#x2018;paint&#x2019; music.', 1262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1263, 'He painted some stage backdrops for experimental orchestral works.', 1263, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1264, 'GERMAN EXPRESSIONISM', 1264, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1265, 'Ernst Ludwig Kirchner', 1265, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1266, 'Kirchner was an early German expressionist painter.', 1266, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1267, 'His paintings are brightly coloured, with angular stylised figures, and lots of brushstrokes.', 1267, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1268, 'Kirchner was the founder of an artists&#x2019; group called die Brucke (The Bridge), which included Kandinsky among its members.', 1268, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1269, 'Die Brucke published a magazine of critical texts called Die Blaue Reiter (The Blue Rider).', 1269, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1270, 'The First World War had a profound effect on artists.', 1270, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1271, 'Oscar Kokoschka, Otto Mueller and others registered their horror at what had happened in their work.', 1271, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1272, 'Max Beckman', 1272, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1273, 'Beckman was a German artist who painted in an expressionist style, choosing to portray the people and social spaces of the day in Berlin.', 1273, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1274, 'A self portrait shows him full length, standing glaring at the viewer while wearing a large black overcoat and a hat with a wide brim.', 1274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1275, 'Beckman used a lot of black to outline his figures.', 1275, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1276, 'Otto Dix', 1276, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1277, 'Dix painted the First World War atrocities, including limbless and horrifically injured soldiers, the best known showing two veterans sitting at a caf&#xe9; table, one of whom has had his leg blown off, the other has an eyeball hanging out.', 1277, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1278, 'George Grosz', 1278, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1279, 'Grosz painted the decadence of the Weimar republic at the beginning of the twentieth century and the aftermath of war.', 1279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1280, 'Paul Nash', 1280, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1281, 'One of the few British artists who made paintings about the war, Nash showed barren landscapes of the trenches and no mans&#x2019; land in a slightly surrealist light, favouring greens and browns and populating his landscapes with skeletal shapes to create an atmosphere of death.', 1281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1282, 'Egon Schiele', 1282, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1283, 'Although Schiele did not directly paint about the war, his paintings are uneasy and cheerless portraits that were in tune with the times.', 1283, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1284, 'The young women and men in Schiele&#x2019;s work are usually emaciated and have hollow faces and large eyes.', 1284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1285, 'His portraits usually show the whole body, sometimes more than one figure, usually naked or semi clothed on pale backgrounds and they are painted with rough brushstrokes and a palette of white with brown, grey and black.', 1285, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1286, 'Throughout the early twentieth century there were plenty of artists who ignored political events and continued to make art that represented romantic, spiritual or domestic subjects.', 1286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1287, 'Balthus', 1287, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1288, 'Balthus is renowned for his domestic interiors and the dreamlike quality of his paintings of young women and girls.', 1288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1289, 'He used a restrained palette and the features of his female sitters are flattened and idealised.', 1289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1290, 'Balthus continued to paint until he was a very old man.', 1290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1291, 'Marc Chagall', 1291, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1292, 'Chagall is a French painter who also designed stained glass.', 1292, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1293, 'He is usually associated with images of lovers and animals who are sometimes flying.', 1293, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1294, 'His narrative paintings are executed in a faux na&#xef;ve style, with soft colours and a sentimental quality.', 1294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1295, 'Chagall often painted images of love and marriage, for example one painting shows a bride and groom resting on a giant hen in the sky, with symbols of the artist&#x2019;s Jewish faith in the background.', 1295, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1296, 'As well as hens and roosters, Chagall liked to paint horses, for example one painting features a white horse with large green eyes and long eyelashes.', 1296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1297, 'Chagall was commissioned to design the stained glass windows for a chapel designed by le Corbusier in the south of France.', 1297, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1298, 'Raoul Dufy', 1298, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1299, 'Known for his idyllic seaside scenes, Dufy used bright colours and quick gestural brushstrokes.', 1299, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1300, 'He was commissioned to paint a mural for the head quarters of the national French electricity generating company celebrating the benefits of electric power.', 1300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1301, 'He made a large curved panorama showing people going about varying activities in the countryside, the city and at the seaside with electricity pylons linking the different scenes.', 1301, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1302, 'Robert Delaunay', 1302, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1303, 'Delaunay made semi abstract paintings using bright, luminous colours, usually in small squares.', 1303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1304, 'He was married to Sonia Delaunay.', 1304, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1305, 'Sonia Delaunay', 1305, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1306, 'As well as making light bright coloured semi abstract paintings, Delaunay is known for her designs for woven and printed textiles.', 1306, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1307, 'Jean Arp', 1307, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1308, 'Arp was a Dutch artist who worked in mixed media and painting, making a lot of wall hung reliefs and constructions using primary colours and white, and simple shapes, usually curved.', 1308, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1309, 'Arp cut out simple shapes from sheets of timber and glued them to a board, adding other elements and painting the whole thing.', 1309, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1310, 'Kees Van Dongen', 1310, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1311, 'Van Dongen made semi abstract colourful paintings, applying the paint quite thickly.', 1311, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1312, 'Nolde and Munch made a new kind of expressionistic landscape painting.', 1312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1313, 'Emile Nolde', 1313, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1314, 'The Belgian artist Nolde&apos;s expressionistic landscapes and portraits are characterised by very bright colours and impasto.', 1314, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1315, 'Edvard Munch', 1315, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1316, 'One of the most famous modern paintings, The Scream, was painted by the Norwegian artist Munch.', 1316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1317, 'This iconic painting has often been used in advertising and has been stolen several times.', 1317, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1318, 'Munch had a very distinctive painting style, which gives the appearance of a woodcut at times.', 1318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1319, 'He outlined his figures, often painting the background to follow the contours of the person in the painting to add to the outlining.', 1319, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1320, 'He used strong and often acidic colours in later works, but many of his earlier landscapes use soft colours and monochrome.', 1320, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1321, 'In The Scream, Munch wanted to suggest both the sound of the scream and the emotion that engendered it.', 1321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1322, 'The figure of a screaming person dressed in black, with shocked eyes and hands to open mouth, is seen on a jetty, surrounded by concentric lines of bright colours that seem to represent the sound of the scream.', 1322, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1323, 'Munch&apos;s subjects were either the rural Norwegian landscape or people.', 1323, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1324, 'There is often a dreamlike quality to his work, as if nothing were quite real; the sun is often a strange colour, shadows are distorted, and elements are coloured unnaturally.', 1324, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1325, 'The people in Munch&#x2019;s work always seem to be or to feel that they are alone.', 1325, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1326, 'A painting of a lake has a setting sun, the reflection of which is a thickly applied vertical yellow stripe on the water.', 1326, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1327, 'In a lithograph called The Singer a woman dressed in black stands in a room with a piano.', 1327, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1328, 'The only bright colour in the painting is in the woman&#x2019;s red hair.', 1328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1329, 'At the time The Scream was painted Freud&#x2019;s theories of hysteria and the unconscious were just becoming known and also influenced the work of the surrealists.', 1329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1330, 'Some artists experimented more literally with the subconscious mind.', 1330, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1331, 'Henri Michaux', 1331, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1332, 'Michaux was a French artist who made small obsessive drawings and written works, dense with scribbling, extremely intricate patterns and landscapes and letters to anonymous recipients written in the smallest of hands, sometimes blanked out after writing.', 1332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1333, 'Michaux mainly used pen and ink, often brown ink, and made his drawings under the influence of mescaline, which Michaux believed allowed him fuller access to his subconscious.', 1333, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1334, 'MC Escher', 1334, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1335, 'The German artist Escher made extremely detailed and precise drawings of fantasy interiors and architecture, using impossible perspective or optical tricks thereby making something appear to change from convex to concave continuously.', 1335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1336, 'His work has been frequently reproduced, for example an interior with a staircase descending around four walls that never goes anywhere, a pattern of black and white doves that becomes something else, and a hand drawing itself which becomes a hand drawing itself.', 1336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1337, 'The endgame of Esher&#x2019;s work is characteristic, everything appears to return to itself.', 1337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1338, 'Some artists made work in a na&#xef;ve or faux na&#xef;ve style.', 1338, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1339, 'Paul Klee', 1339, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1340, 'The French painter Klee made a large number of small paintings and an enormous range of works on paper, using both drawing and printmaking.', 1340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1341, 'Klee habitually used thin drawn lines to make geometric patterns, often repeated triangles or squares with dots, which were coloured and often resemble patchwork.', 1341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1342, 'Sometimes these remained as abstract patterns, at other times Klee would draw figures, trees, buildings or animals.', 1342, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1343, 'Jan Dubuffet', 1343, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1344, 'Dubuffet used sand to roughen the texture of his paint.', 1344, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1345, 'He painted large simple figures and faces which owed something to African art but also to graffiti.', 1345, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1346, 'Auguste Maillol', 1346, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1347, 'Maillol&apos;s bronze and stone sculptures have solid and rounded forms, as if they cannot escape from the block from which they are carved.', 1347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1348, 'The bodies are distinctively simply formed, and even the smaller works have a gentle monumental quality.', 1348, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1349, 'Artists&#x2019; groups were sometimes centred on a particular location.', 1349, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1350, 'The St Ives group is named after a town in the southwest of England to which they migrated to avoid the Blitz and because the quality of light was very good for painting.', 1350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1351, 'Many of them stayed.', 1351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1352, 'THE ST IVES GROUP', 1352, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1353, 'Barbara Hepworth', 1353, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1354, 'A British sculptor who began working in the 1940s, Hepworth made the work for which she is best known in the artist colony of St Ives in Cornwall, south west England, where she spent most of her working life, along with Ben Nicholson and others.', 1354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1355, 'She was also a contemporary of Henry Moore.', 1355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1356, 'Hepworth worked in stone, wood and metal, as well as making working drawings.', 1356, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1357, 'Her sculptures were smooth, often oval forms, which sometimes have holes (or voids) through them.', 1357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1358, 'The voids might be spanned by string or wire strung across in parallel lines or fanning out like spokes, as if to create some kind of tension in the object.', 1358, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1359, 'Hepworth favoured highly polished black or white marble, granite, wood or bronze.', 1359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1360, 'The sculptures ranged from small table sized ones, for example three perfectly smooth elliptical forms on a shallow plinth all made of white marble, or an elongated bronze shape standing on its end, to medium sized plinth based works such as the stringed elliptical voids, to large outdoor sculptures that sat on the ground, on stone boulders, or bronze plinths.', 1360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1361, 'Hepworth made several large scale public commissions and her work can be seen in London on the fa&#xe7;ade of John Lewis, a London department store, in various public parks, for example on Hampstead Heath and in Battersea Park, and towering over the piazza of the United Nations building in New York.', 1361, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1362, 'In most cases these works feature an oval shape often with strings, either in stone or bronze.', 1362, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1363, 'For the UN building she made a large oval flat shape with a small hole through it, reminiscent of a stone standing on its end, which is placed next to an ornamental water feature.', 1363, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1364, 'The standing stones and other Stone Age monuments and monoliths that are common in Cornwall were part of her inspiration and Hepworth wanted her sculptures to sit in the landscape in the same way.', 1364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1365, 'Ben Nicholson', 1365, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1366, 'Nicholson was a leading member of the St Ives group and a contemporary of Barbara Hepworth who pioneered a style of work that is a cross between constructivism and geometric abstraction.', 1366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1367, 'His paintings often have raised areas made by shapes cut from plywood.', 1367, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1368, 'He used white and grey and added lines and smaller areas of brighter colours.', 1368, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1369, 'He also made representational works, most of which feature the Cornish land and seascapes.', 1369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1370, 'Winifred Nicholson', 1370, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1371, 'St Ives painter.', 1371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1372, 'Terry Frost', 1372, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1373, 'A younger British artist who was a member of the St Ives group in the 1950s and 60s.', 1373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1374, 'Frost made abstract pattern paintings, using irregular squashed circular shapes in a repeated pattern, in black and white with red, dark green, blue and other colours.', 1374, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1375, 'Sometimes the paintings would consist of a part of a large solid black circle on one side of the canvas, and a part of a red circle on the opposite side.', 1375, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1376, 'The clean lines, minimal forms, bright colours and black and white of Frost&#x2019;s paintings were very in tune with contemporary fashion and design.', 1376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1377, 'Naum Gabo', 1377, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1378, 'An eastern European artist who lived and worked in Britain, Gabo made sculptures and maquettes for proposed sculptures from wood, metal, acrylic, wire and thread.', 1378, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1379, 'Gabo&#x2019;s formal abstract structures have a strong architectural element in their reliance on apparent tension and cantilevering for their structural strength.', 1379, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1380, 'They are clearly influenced by Russian constructivism and Suprematism, but they also relate to the sculptural forms of Barbara Hepworth, in which voids and solid form are often given tension by thread or wires stretched across in parallel lines.', 1380, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1381, 'Most of his work is very small, around 40 cm high.', 1381, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1382, 'Gabo&#x2019;s use of very new materials and his architectural forms made him unique in his time, and he developed a body of work that is singular in its devotion to an aesthetic and to material.', 1382, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1383, 'He also made preparatory drawings and sketches.', 1383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1384, 'Peter Lanyon', 1384, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1385, 'A St Ives painter who painted semi abstract landscapes using a lot of green, brown and white.', 1385, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1386, 'Alfred Wallis', 1386, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1387, 'Walllis painted the harbours, fishing boats and the sea around St Ives, often using an eccentric perspective that combined aerial and frontal views.', 1387, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1388, 'THE COBRA GROUP', 1388, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1389, 'This was a group of artists working in Holland who made semi abstract paintings during the 1940s and 50s.', 1389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1390, 'Karel Appel', 1390, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1391, 'Appel was the leader of the CoBRA group.', 1391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1392, 'His paintings of figures with smiling toothy faces are made with bright colours and lots of impasto.', 1392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1393, 'ABSTRACTION', 1393, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1394, 'Malevich and Kandinsky had given the fullest expression to early abstraction.', 1394, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1395, 'By the 1940s abstraction was developing fast both in Europe and most particularly in America.', 1395, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1396, 'Many painters who had begun their careers painting figuratively turned to abstraction, de Kooning being one example.', 1396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1397, 'Some made works that were minimal in style, others worked towards abstract expressionism.', 1397, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1398, 'Willem de Kooning', 1398, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1399, 'An American artist who worked from the 1950s to the 1990s, de Kooning made paintings in a great variety of styles, from figurative to abstract.', 1399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1400, 'He is best known for two periods of his work, the first made in the 1950s and consisting of a series of small portraits of women grinning with lots of teeth, painted in an almost impossibly thick and encrusted impasto, the surface of the canvas heavy with blobs of multi coloured paint that project from its surface producing an overall brown colour in combination.', 1400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1401, 'Like Rothko, de Kooning did not subscribe to the notion of the artist as knowing subject but to the Kantian idea of pure art.', 1401, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1402, 'De Kooning&#x2019;s second well known group of works are the controversial late paintings, made after the artist was diagnosed with Alzheimer&#x2019;s disease.', 1402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1403, 'These are very large paintings made with thin bright primary colours of paint applied in single brush strokes that barely cover the white primed surface of the canvas giving the impression of a white painting roughly covered in gestural marks.', 1403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1404, 'Some critics considered them to be an extraordinary late flowering, others that they were inconsequential in de Kooning&apos;s oeuvre due to his mental state.', 1404, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1405, 'De Kooning is vilified by American artist Paul McCarthy in a film in which McCarthy appears dressed as a paint tube, squirting paint everywhere and chanting &#x2018;de Kooning, de Kooning&#x2019; in an infantile way.', 1405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1406, 'Josef Albers', 1406, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1407, 'An American painter born around 1900, Albers made geometric abstractions usually based on the square, using dull versions of primary colours.', 1407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1408, 'He was interested in the optical effects of colours on each other.', 1408, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1409, 'Albers was a lifelong teacher of art and as is discussed in Eva Hesse&#x2019;s posthumously published diary as her professor.', 1409, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1410, 'Yves Tanguy', 1410, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1411, 'Tanguy was a French artist who made semi abstract paintings showing organic sculptural forms.', 1411, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1412, 'Tanguy also made kinetic sculptures (the best known of which is in Paris outside the Centre Pompidou) consisting of similar forms that were constructed so that they would be animated by cause and effect, such as wind moving a vane, or water flow.', 1412, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1413, 'Every movement of the sculpture creates sounds.', 1413, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1414, 'Ad Reinhardt', 1414, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1415, 'An American artist who made minimal abstract paintings, mostly in grey and black, from the 1960s to 80s.', 1415, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1416, 'Clyfford Still', 1416, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1417, 'Still&#x2019;s abstract paintings often have large areas of flat colour to which he adds a contrasting area, the rough edge of which encroaches on the predominant colour.', 1417, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1418, 'Antoni Tapies', 1418, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1419, 'A Spanish painter who made abstract paintings that resemble doors and walls.', 1419, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1420, 'Tapies used textural materials and built up the surface of his canvas to create paintings that are almost reliefs, in predominantly natural colours such as dark brown, black and white.', 1420, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1421, 'Robert Ryman', 1421, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1422, 'Ryman is known as the white on white painter; he only used white paint (although he often used a bright coloured ground).', 1422, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1423, 'Ryman&#x2019;s paintings are mostly small, they are neatly made but with quite thick paint and lots of blobs and brushstrokes.', 1423, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1424, 'Robert Motherwell', 1424, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1425, 'An American abstract expressionist painter who made very big paintings often using a lot of black paint applied with large brushes and leaving other areas as bare canvas.', 1425, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1426, 'Leon Golub', 1426, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1427, 'American artist born in the 1930s who made abstract paintings.', 1427, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1428, 'Elizabeth Murray', 1428, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1429, 'An American artist who made wall reliefs and constructions that she called three dimensional paintings.', 1429, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1430, 'Victor Pasmore', 1430, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1431, 'British artist who made abstract paintings and works on paper.', 1431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1432, 'Eileen Agar', 1432, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1433, 'A British artist who made sculptures and reliefs, both abstract and symbolist, as well as some small objects.', 1433, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1434, 'Mel Bochner', 1434, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1435, 'Bochner&#x2019;s characteristic works are dull coloured semi abstract cityscapes in a geometric hard edged style.', 1435, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1436, 'Morris Louis', 1436, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1437, 'Louis is an American artist who is known for his abstract pour paintings made in the 1960s and 70s.', 1437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1438, 'Louis developed a technique for pouring paint onto raw canvas and allowing the paint to pool and spread, soaking into the canvas yet allowing the colours to remain distinct from one another.', 1438, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1439, 'The resulting works usually consist of brightly coloured stripes emanating from one side of the canvas, spreading and blending on the edges, with the texture of the surface of the canvas always visible.', 1439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1440, 'Frank Stella', 1440, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1441, 'An American artist who made wall drawings and reliefs, which consisted of painted cut outs arranged as an abstract assemblage on a panel fixed to the wall.', 1441, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1442, 'Lucio Fontana', 1442, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1443, 'The Italian artist Fontana&#x2019;s paintings from the 1950s and 60s are abstract, plain and flat coloured canvases with slits cut right through the canvas.', 1443, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1444, 'Sometimes Fontana added some textural detail, such as painted gravel or wool thread.', 1444, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1445, 'He used a range of colours from dark reds and blues to bright copper green.', 1445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1446, 'Sometimes his paintings are made on egg shaped canvases.', 1446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1447, 'Mary Heilman', 1447, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1448, 'An abstract painter born in the 1940s, Heilman makes small paintings of carefully considered abstract shapes, lines and forms exploring endless possibilities of form and colour.', 1448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1449, 'Al Held', 1449, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1450, 'Twentieth century American painter.', 1450, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1451, 'Howard Hodgkin', 1451, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1452, 'Hodgkin is a British painter born in the 1940s who makes abstract paintings.', 1452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1453, 'He uses very bright jewel like colours, applied in large, often round, repeated splodges, the paint continuing right off the edge of the canvas onto and round the frame.', 1453, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1454, 'Hodgkin&#x2019;s paintings are never larger than 2 metres high.', 1454, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1455, 'He sometimes uses round and oval shaped canvases.', 1455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1456, 'Hodgkin has made work for public commission including a large photomural of brushstrokes that fills the circular facade of an Imax cinema in London.', 1456, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1457, 'Bridget Riley', 1457, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1458, 'Riley is famous for her Op Art black and white paintings made in the 1960s, work which endures as one of the most recognisable images of the 1960s.', 1458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1459, 'She made these paintings by drawing and distorting grids and filling them in with black and white.', 1459, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1460, 'The distortions create illusions of curves, of shimmering and of motion making the paintings hard to look at.', 1460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1461, 'Riley used grids of squares, triangles, as well as dots and ellipses and parallel lines.', 1461, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1462, 'One painting, one metre high, has a grid of squares that gradually decrease in width as they move toward the centre of the painting, creating the illusion of two vertical chequered cylinders.', 1462, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1463, 'Another painting, one and a half metres by two metres, has parallel horizontal wavy lines, each line fractionally further to one side of the painting than the next, creating an optical shimmer.', 1463, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1464, 'A large, two metre square painting has black elliptical dots placed about 30 cm apart on a grid, the angle of each ellipse changing gradually, giving an impression of motion.', 1464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1465, 'A triangle pattern creates waves as each of the triangles on the square canvas is progressively tilted along a curved line.', 1465, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1466, 'Riley made a large number of black and white works before beginning to add one or two colours, for example yellow, red and blue, to the black and white paintings.', 1466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1467, 'A horizontal wavy line painting has colour added.', 1467, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1468, 'In the 1980s Riley began to explore the optical colour blending effects she had created, and made the first of a large number of pure colour works.', 1468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1469, 'She ceased to use black and white and has never returned to it.', 1469, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1470, 'She continued to study the work of C&#xe9;zanne and to refer to his paintings in her geometric abstractions, many of which draw directly on historical painting.', 1470, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1471, 'Works from this period are mostly a grid of multicoloured parallelograms, the choice of colour influenced by the source image.', 1471, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1472, 'These images predate but later seemed to anticipate pixellation.', 1472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1473, 'Riley has made many public commissions including applying bands of coloured stripes to the corridors on several floors of a London hospital.', 1473, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1474, 'During the late 1990s and early 2000s Riley continued to use colour but began to draw much larger shapes.', 1474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1475, 'The shapes in her paintings remain hard edged but she ceased to use a grid.', 1475, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1476, 'The tendencies evident in early twentieth century abstract painting developed into two distinct but complementary movements, abstract expressionism and minimalism.', 1476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1477, 'ABSTRACT EXPRESSIONISM', 1477, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1478, 'The critic Clement Greenberg argued for Abstract Expressionism as the only logical way forward for painting.', 1478, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1479, 'He supported many of its best exponents, including Pollock.', 1479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1480, 'Jackson Pollock', 1480, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1481, 'The best known of the American abstract expressionist painters and arguably the best known modernist painter of all time.', 1481, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1482, 'Pollock was born in the 1920s and died in the early 70s in a car accident.', 1482, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1483, 'Pollock began working in the 1950s and at the end of the decade he started to experiment, placing the canvas on the floor and using a brush to pour house paint, not touching the canvas at all.', 1483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1484, 'This was a radical step, since no one had ever made a painting without touching the canvas and with so little control over the result.', 1484, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1485, 'Pollock&#x2019;s drip paintings caused a sensation.', 1485, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1486, 'His new method became known as action painting.', 1486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1487, 'The photographer Hans Namuth made a seminal film of Pollock showing him pouring paint on the canvas, which included a section filmed from below through glass.', 1487, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1488, 'The action paintings are up to 2 metres high and very wide and are all composed of an all over &#x2018;pattern&#x2019; of drips, applied in a dynamic but highly controlled way, so that a design is evident.', 1488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1489, 'Far from relinquishing control, Pollock became master of the technique.', 1489, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1490, 'The combinations of colours are subtle, usually involving black and white with one or two other colours.', 1490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1491, 'One of the best known is Blue Poles, which has two vertical blue stripes amidst the swirling drips.', 1491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1492, 'Another, titled One, is a largely black and white composition.', 1492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1493, 'Pollock made many public commissions and his work was taken up by the American government as representing the pinnacle of modernist achievement in art.', 1493, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1494, 'His work was seen as symbolising the freedom of the American way of life.', 1494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1495, 'Unwittingly Pollock&#x2019;s work was used as US propaganda against the Soviet Union, when the CIA covertly funded an international touring exhibition of the work of the abstract expressionists designed to be compared directly and unfavourably with soviet socialist realist art.', 1495, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1496, 'Pollock was married to Lee Krasner, also an abstract painter.', 1496, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1497, 'Krasner saw Pollock through many years of increasing alcoholism and infidelity, taking him to live and work in a house on Long Island to help him stop drinking, until she felt compelled to leave him although she continued to care for him.', 1497, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1498, 'Krasner subjugated her own career to Pollock&#x2019;s and it seems reasonable to suppose that he was unlikely to have become successful, or to have even made the action paintings, without her support.', 1498, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1499, 'Susan Rothenstein', 1499, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1500, 'American abstract expressionist painter.', 1500, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1501, 'Franz Kline', 1501, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1502, 'American Kline&#x2019;s enormous abstract expressionist paintings usually feature large black gestural marks made with a big brush on a white, or even un primed ground.', 1502, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1503, 'Much of the ground is left untouched but it becomes an active part of the surface of the painting.', 1503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1504, 'Lee Krasner', 1504, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1505, 'American figurative painter who turned to abstraction.', 1505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1506, 'She established a foundation in her own and her husband Jackson Pollock&#x2019;s names, which through its grant making activities contributes to the careers of many artists.', 1506, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1507, 'Helen Frankenthaler', 1507, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1508, 'American abstract expressionist painter.', 1508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1509, 'Barnett Newman', 1509, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1510, 'American painter Newman&#x2019;s minimal paintings are known for &#x2018;the zip&#x2019;, a line of a contrasting colour running vertically down the canvas.', 1510, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1511, 'Newman invariably used one or two solid colours in blocks or bands, often dark blue, black and maroon, but also golden ochre colours and aquamarine, and the zip (red on a dark brown ground for example) animated these, setting up an optical resonance.', 1511, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1512, 'He spent his whole career painting these and like Rothko was held up as a spiritual painter.', 1512, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1513, 'One group of paintings on a single theme fills a whole room; they are white on white paintings with elements of black.', 1513, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1514, 'Mark Rothko', 1514, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1515, 'Rothko is an American painter who is one of the most famous exponents of abstract expressionism.', 1515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1516, 'Rothko&#x2019;s works are simple colour fields, predominantly one or two shades of the same colour or two contrasting colours, often arranged as a wide border with a central section and usually in portrait format.', 1516, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1517, 'Although the colour is solid, it is roughly painted with an uneven edge so that the colours affect each other optically.', 1517, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1518, 'Rothko&#x2019;s paintings are quite large, up to 3 metres high and he sometimes made four works to be shown together.', 1518, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1519, 'One such installation is a dark red group of paintings consisting of blurred rectangles within borders.', 1519, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1520, 'This installation provokes a spiritual or contemplative response in many viewers, some of whom say they are moved to tears.', 1520, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1521, 'These works are often used as exemplification that art can provide a transcendental experience.', 1521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1522, 'Rothko referred to his paintings as parts of himself, describing them as skins hung on the wall.', 1522, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1523, 'MINIMALISM', 1523, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1524, 'In the late 1950s and early 60s minimalism was an emerging trend in both painting and sculpture.', 1524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1525, 'Minimalist sculpture was groundbreaking in it refusal of any form of modelling, and in its use of prefabricated materials.', 1525, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1526, 'Robert Morris', 1526, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1527, 'An American sculptor who was known for his use of fabricated steel and other metals.', 1527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1528, 'Morris made abstract minimal sculptures, which were nearly always cube shapes, about one and a half meters high, open at the top.', 1528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1529, 'His series of copper plated boxes shown as a group are particularly well known, as well as a similar series made of mirrored glass.', 1529, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1530, 'The copper boxes emit a glowing pink reflected light from their interiors.', 1530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1531, 'These are contradictory works in terms of their representation of a heavy solid mass by means of emptiness and light.', 1531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1532, 'Morris also made sculpture with pieces of heavyweight felt that he scattered on the floor.', 1532, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1533, 'He collaborated in a live performance with Carolee Schneeman in the 1970s titled Olympia.', 1533, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1534, 'Richard Serra', 1534, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1535, 'An American artist who is well known for his monumental sculpture in steel, Titled Arc, which was installed in a public plaza in the 1980s.', 1535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1536, 'Tilted Arc was a curving steel wall that bisected the plaza and was tilted at a steep angle along its length.', 1536, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1537, 'It became notorious for the degree of public resistance to it (the sculpture created a detour making the walk across the square longer), and for the fact that a worker was killed when a part of the sculpture fell on him during installation.', 1537, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1538, 'Serrra&#x2019;s work consisted of mostly welded steel sculpture, but not always on such a scale.', 1538, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1539, 'An early video work, Hand Catching Lead, shows the sculptor&#x2019;s hand trying repeatedly to catch a piece of falling lead, a difficult task which is rarely successful.', 1539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1540, 'Donald Judd', 1540, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1541, 'American Donald Judd is one of the most important of the minimal sculptors.', 1541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1542, 'He made steel boxes, shelf like structures and repeated units, fabricated with a high attention to detail and immaculately spray painted in a variety of colours.', 1542, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1543, 'Some sculptures are made of polished metal such as brass, so that they are extremely shiny.', 1543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1544, 'The structures and units are ambiguous, suggesting function but obviously non functional.', 1544, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1545, 'They are either mounted on the wall, in a horizontal line or one above the other, sometimes in ascending sizes, or placed with precision on the floor.', 1545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1546, 'The I Beam is one of Judd&#x2019;s favourite materials; he pioneered the use of pre fabricated steel and modular construction in his sculptures creating simple works that often had a monumental quality.', 1546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1547, 'Judd set up a studio and a foundation in Marfa, Texas.', 1547, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1548, 'Carl Andre', 1548, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1549, 'Andre is another of the leading artists in the generation of American minimalist sculptors that includes Judd and Morris.', 1549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1550, 'He is notorious for his &#x2018;pile of bricks&#x2019;, purchased by the Tate gallery in London in 1980, which was derided in the press for being nothing but a pile of ordinary house bricks.', 1550, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1551, 'This work, an arrangement of house bricks to form a plinth two bricks thick, was similar to his other works, chiefly floor works consisting of metal tiles arranged in rectangles and lines.', 1551, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1552, 'It was important for the viewer&#x2019;s experience of the work that they were free to walk on the sculpture.', 1552, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1553, 'These works are both self effacing in their near invisibility and grandiose in their ambition.', 1553, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1554, 'Andre said that they represented footprints of much larger structures.', 1554, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1555, 'He wanted to imply monolithic structures through minimal and economic means, creating a tension between the monolithic and the invisible.', 1555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1556, 'Andre also made a number of text works, some with &#x2018;x&#x2019;s and &#x2018;o&#x2019;s typed in rows, and others consisting of concrete poetry made by fitting words into some kind of geometric system.', 1556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1557, 'Brice Marden', 1557, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1558, 'American painter of minimal abstract works who made large (often at least 2 by 3 metre) canvases which are painted in muted colours, often grey with one or two contrasting coloured stripes on the edge of the canvas.', 1558, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1559, 'Marden&apos;s work has similar formal qualities to the work of Barnett Newman, although where Newman&apos;s work is painterly, Marden&#x2019;s is hard edged and painted with flat solid colour.', 1559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1560, 'Agnes Martin', 1560, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1561, 'Martin&#x2019;s minimal abstract paintings are usually based on a grid and they are mainly white with pencil thin lines of bright colours.', 1561, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1562, 'The detail of the painting is barely perceptible from a distance; they are cool, calm and full of light, and rigorous in their execution.', 1562, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1563, 'John McCracken', 1563, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1564, 'A British artist who makes minimal abstract sculptures in the form of planks and cubes with a high gloss lacquered finish in solid colours.', 1564, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1565, 'The planks (about 3 metres long, 50 cm wide and 10 cm deep) typically lean against the gallery wall, while other sculptures are hung from the wall.', 1565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1566, 'Yvonne Rainer', 1566, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1567, 'An American choreographer who worked with artists such as Robert Rauschenberg and Jasper Johns, as well as musicians such as John Cage on collaborative performance works, for example The Mind is a Muscle, made in 1971.', 1567, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1568, 'These works were developed largely at the Black Mountain College summer school and at the Judson Church Centre in New York and were unusual in their day for being multidisciplinary.', 1568, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1569, 'Rainer choreographed dance works based on the repetition of everyday movements eschewing classical dance form and skills.', 1569, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1570, 'This emphasis on the everyday had its parallels in both minimalism and Pop Art.', 1570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1571, 'Rainer later went on to become a filmmaker and in the 1990s made her first feature film.', 1571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1572, 'TOWARDS POP ART', 1572, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1573, 'Artists such as Rauschenberg, Johns and Lichtenstein took the logic of abstraction and minimalism and applied it to everyday objects and images.', 1573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1574, 'Their innovations paved the way for pop art.', 1574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1575, 'Robert Rauschenberg', 1575, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1576, 'Rauschenberg began his career in the late 1950s and was part of New York pop art in the 60s.', 1576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1577, 'He worked in all media and is particularly known for his paintings to which objects are attached.', 1577, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1578, 'The object would be made part of the painting or in some cases a painting be made part of a sculpture by extending the paint from canvas to object.', 1578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1579, 'Rauschenberg&#x2019;s innovation was to use screen printing as a medium, transferring images onto his canvases even before Warhol did, in particular photographic images from newspapers, cityscapes and street signs, before adding paint and even found objects.', 1579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1580, 'One of his best known paintings features a multi layered image of a city with a stop sign, a sign that reads &#x2018;one way&#x2019; and architectural elements and abstract areas of colour.', 1580, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1581, 'Another has a photographic transfer of President Kennedy.', 1581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1582, 'Rauschenberg made many works from found images and objects.', 1582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1583, 'One painting features a wooden chair attached to the canvas, and in another a single mattress with sheets, pillow and blankets becomes the canvas and is hung on the wall and painted on.', 1583, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1584, 'Rauschenberg&apos;s conceptual painterly abstraction was important in the early development of pop art.', 1584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1585, 'He also made many drawings, including notably one called &#x2018;Erased de Kooning&#x2019;, which was simply that: a drawing by de Kooning erased by Rauschenberg.', 1585, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1586, 'Rauschenberg worked with Merce Cunningham, the dancer and member of the Judson Church collective of artist and dancers which including choreographer Yvonne Rainer, designing sets, lighting and costumes for dance performances.', 1586, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1587, 'He would often paint the set and the costumes himself.', 1587, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1588, 'For one dance work he made a canvas backdrop painted with spots and matching spotted bodysuits for the dancers.', 1588, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1589, 'Jasper Johns', 1589, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1590, 'American artist born in the 1930s, Johns was one of the artists who made the move from figuration to abstraction in the 1950s, and then in the 1960s began to use recognisable symbols in his paintings, the best known being the American flag.', 1590, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1591, 'Johns and his contemporary Rauschenberg paved the way for Pop Art.', 1591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1592, 'Johns&#x2019;s target paintings use a circular target motif (the kind used for archery or shooting) of black and white, or red yellow and blue.', 1592, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1593, 'The paintings are portrait format so that the circular target is placed in the picture plane and there are sometimes other elements in the composition.', 1593, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1594, 'Johns&#x2019;s American flag paintings were innovative for their use of a pre existing symbol to make an abstract image; they are simply painted American flags, the stars and stripes covering the canvas edge to edge.', 1594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1595, 'These paintings were also significant because at the time the American flag was being burnt by protesters against the Vietnam War.', 1595, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1596, 'Johns went on to make a proliferation of flag paintings, drawings and lithographs usually in red, white and blue.', 1596, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1597, 'Then he began changing the colours culminating in a series of black on black and white on white flags, and even an edition of bronze flag table sculptures.', 1597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1598, 'Johns also made a series of number paintings, simply painting the numbers zero to nine, drawn using a stencil to fill a large canvas edge to edge.', 1598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1599, 'These were made in many versions including white on white.', 1599, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1600, 'The idea to make an ordinary object into an art object led Johns to make some bronze sculptures, the best known of which are the Beer Cans and the Can of Brushes.', 1600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1601, 'These life size replicas are painted in true to life colours.', 1601, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1602, 'Roy Lichtenstein', 1602, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1603, 'Lichtenstein&#x2019;s work is among the best known of the American pop artists.', 1603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1604, 'He made paintings using images from printed cartoon magazines by taking single frames or even a detail from a frame and enlarging it, initially to about 1 metre high but eventually to a much larger size.', 1604, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1605, 'He then made a painting from the drawing, reproducing exactly what he saw including any text.', 1605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1606, 'Initially the paintings were black and white but Lichtenstein soon moved to use colour.', 1606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1607, 'The paintings nearly always feature a person, a part of a vehicle and a graphic or textual depiction of fire, speed or force; they are part of a larger narrative that we are left to guess at.', 1607, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1608, 'Eventually Lichtenstein began to paint the dots made by the printing process, the dots which are obvious on billboards when they are viewed close up.', 1608, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1609, 'By making the dots part of the painting Lichtenstein was reproducing both the reproduction and the means of its reproduction and actually painting the printing process.', 1609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1610, 'He used the cyan magenta and yellow process colours on a white ground with black.', 1610, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1611, 'Certain of Lichtenstein&#x2019;s works are iconographic, for example one of a fighter pilot in a cockpit of a plane that has a yellow flash coming from the fuselage.', 1611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1612, 'The text announces the pilot&#x2019;s thoughts at that moment.', 1612, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1613, 'Another is of a glamorous woman crying, again with text revealing her thoughts.', 1613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1614, 'His style was, and still is, copied, plagiarised and borrowed.', 1614, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1615, 'POP ART', 1615, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1616, 'Andy Warhol', 1616, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1617, 'Warhol is one of the most significant artists of the late twentieth century.', 1617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1618, 'He was born in the 1930s and began his career as a graphic designer in his twenties.', 1618, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1619, 'He was very accomplished at drawing and became an artist.', 1619, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1620, 'Warhol is best known for his Campbell&#x2019;s Soup Can paintings and his Marilyn paintings, but these are only a small part of his extremely prolific output.', 1620, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1621, 'Warhol&#x2019;s early graphic work included advertisements for shoe shops, clothes shops, children and adult book illustrations, book jackets and packaging.', 1621, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1622, 'He used pen and ink, colour and sometimes added gold leaf.', 1622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1623, 'He began to make screen prints.', 1623, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1624, 'Warhol became an artist and turned his studio into a gathering place and workshop called The Factory.', 1624, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1625, 'He made his own work at The Factory but by virtue of his eccentric personality and arresting style began to gather around him a coterie of colleagues, assistants and admirers.', 1625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1626, 'Warhol&#x2019;s hair was bleached white and he was never seen without dark glasses on and in stylish clothes.', 1626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1627, 'He was close to the most inspiring people in the fashion, music and art worlds.', 1627, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1628, 'It is often said that Warhol himself and The Factory are productions of Warhol&#x2019;s art; certainly Warhol&#x2019;s persona was unique and The Factory was an unprecedented example of collaborative practice.', 1628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1629, 'At The Factory Warhol worked with photographer Billy Name, who documented everything that happened there, models such as Viva and Edie Sedgwick (among others), who were really his muses, actors and any young and beautiful people who interested him.', 1629, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1630, 'The force of Warhol&#x2019;s personality and the mystique that he created around himself meant that people were very keen to work with him or to commission him to make a portrait.', 1630, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1631, 'Warhol was obsessed with fame.', 1631, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1632, 'Sedgwick and Viva starred in Chelsea Girls, Warhol&#x2019;s only feature film.', 1632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1633, 'Many other short experimental films were made at the factory including Empire State, a single static shot of the Empire State building 24 hours long, that documented the changing light on the building.', 1633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1634, 'Warhol said he wanted to make a film that people could watch when they were stoned.', 1634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1635, 'The Screen Tests are a series of head and shoulder shots of just about anyone who passed through the doors of the factory, including many who years later became well known, those who didn&#x2019;t, and those who were well known at the time.', 1635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1636, 'Warhol would simply ask the person to sit and look at the camera.', 1636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1637, 'Warhol published a groundbreaking fashion, music and art magazine called Interview and made a series of television chat shows for which he interviewed people.', 1637, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1638, 'Underpinning all this activity was the continuous production of Warhol&#x2019;s paintings.', 1638, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1639, 'Warhol took the most ordinary mass produced object and represented it as art, making a photographic silk screen of the label on a Campbell&#x2019;s soup can.', 1639, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1640, 'He did this as an anti art gesture, believing like other pop artists that art did not need to have noble subject matter and that art was a commodity like any other.', 1640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1641, 'To this end he used images of coke bottles, Brillo pad boxes and cornflake boxes among others to make his paintings, repeating the colour images in rows to cover the canvas, robbing the image of its original meaning.', 1641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1642, 'He produced these in multiples, denying them any exclusivity.', 1642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1643, 'He also made sculptures of plywood replica Brillo boxes in the same way.', 1643, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1644, 'Warhol made a screen print from a photograph of Marilyn Monroe to which he added paint by hand on the lips, eyes and hair.', 1644, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1645, 'He made as many of these as he felt like, painting each one differently.', 1645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1646, 'Multiples of the Marilyns, each one always the same size (1 metre high), are often hung in rows and blocks and they have become so famous as to be almost ubiquitous, exactly as Warhol would have wanted.', 1646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1647, 'He was attracted to Monroe because of her fame and glamour and made a vast number of paintings of her including a pair of round canvases painted gold, with her image printed in black on one and the other left blank.', 1647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1648, 'As well as the Marilyns, Warhol made a large number of paintings of Chairman Mao in the same way.', 1648, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1649, 'He also made a number of images of an Electric Chair, again made in a wide variety of colour schemes, as well as a Last Supper, and repeated images of Jesus on one canvas.', 1649, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1650, 'His very numerous portrait commissions, which were a mainstay of the Factory&#x2019;s finances, included Jackie Onassis, Joan Collins, Elvis and many society and business figures.', 1650, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1651, 'Warhol also made a number of self portraits, including one with sticking up hair.', 1651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1652, 'Towards the end of his life Warhol made some collaborative paintings with Jean Michel Basquiat.', 1652, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1653, 'He died in the 1980s.', 1653, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1654, 'Claes Oldenburg', 1654, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1655, 'This American artist is known for his soft sculptures that he began to make in the 1960s.', 1655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1656, 'Along with Warhol, Oldenburg was the main pop art sculptor.', 1656, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1657, 'He worked in a number of different media and also made a large number of working drawings.', 1657, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1658, 'The soft sculptures are made of canvas or vinyl, sewn and stuffed in the manner of soft toys, and then painted.', 1658, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1659, 'The sculptures represent vastly enlarged objects such as a light switch made in white vinyl, a drum kit made in painted canvas and a hamburger.', 1659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1660, 'Each are accurately scaled up and constructed, but stuffed loosely so that they sag and collapse.', 1660, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1661, 'The light switch (about one metre square) hangs drooping on the wall, the drum kit (3 metres across) flops in a heap on the floor.', 1661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1662, 'Oldenburg also made many painted clay sculptures, roughly modelled and painted, some cast in bronze, of which one of a hamburger is the best known.', 1662, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1663, 'In the 1970s Oldenburg began to make public sculpture and also made a large number of designs, plans and sketches for monumental works, which were not always realised.', 1663, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1664, 'These include a 30 metre high lipstick monument, a building based on the head of Mickey Mouse and one based on an electrical plug.', 1664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1665, 'Ed Ruscha', 1665, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1666, 'Ruscha became well known in the late 1960s for his paintings of words.', 1666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1667, 'Ruscha took the sign and the billboard as his inspiration and made the painted word the subject of his work; he is best known for his painting of the Hollywood sign.', 1667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1668, 'Ruscha used a variety of typefaces and three dimensional letters in his work, and also made a series of paintings of words as substance, for example the word &#x2018;oil&#x2019; painted to look like oil.', 1668, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1669, 'He also made landscape paintings to which words are added.', 1669, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1670, 'Sometimes Ruscha used a (literal or imaginary) diagonal line in his paintings that he attributes to the compositional elements in classical painting.', 1670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1671, 'James Rosenquist', 1671, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1672, 'Rosenquist has made some of the largest paintings of any contemporary artist.', 1672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1673, 'As a pop artist he is distinguished by his skill for painting on a vast scale acquired during his years as a professional billboard painter, painting images on hoardings above Times Square in New York for example.', 1673, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1674, 'Rosenquist is known for two paintings in particular, made in 1961, both of which are 4 or 5 metres high and around 25 metres long.', 1674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1675, 'F111 shows an American military aircraft, the painted lady on its side, and various other military items alluding to the contemporary Vietnam War protest movement.', 1675, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1676, 'The other work shows a collage of items of Americana of varying relative sizes, such as hugely enlarged tinned spaghetti, celebrating the emerging consumer culture in tune with the spirit of the times.', 1676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1677, 'Rosenquist&#x2019;s paintings often include the image of an idealised woman.', 1677, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1678, 'Rosenquist was a contemporary of Andy Warhol and shared much of the same subject matter, but the two artists were unaware of each other&#x2019;s work until late in the 1960s.', 1678, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1679, 'Rosenquist continued to work on the same scale throughout his career refining his technique with new digital imaging technology to help it became very far removed from his original billboard style.', 1679, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1680, 'In the late 1999s onwards, he made a return to the way he had worked in the 1960s.', 1680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1681, 'Patrick Caulfield', 1681, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1682, 'On of the best British pop artists, Caulfield is known for his very distinctive hard edged representative paintings of domestic interiors.', 1682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1683, 'He chose to paint interiors or elements from interiors such as furniture, lighting and ceramics, and developed a way of making paintings that he never deviated from.', 1683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1684, 'Caulfield copies the most basic structure of a scene from a photograph, rendering the forms with the minimum of line possible.', 1684, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1685, 'He treats light and shadow as solid object and draws both in the same way so that the light from a table lamp will be represented as a solid yellow shape, the shadow behind its shade as a black shape.', 1685, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1686, 'All the objects in a painting are given equal importance, since every element is treated the same.', 1686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1687, 'The outlines are painted in flat acrylic using a schematic, dramatically simplified black outline with the objects, walls, floors, light fittings, furniture being filled in with bright colours.', 1687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1688, 'These black lines are vaguely reminiscent of the lead in a stained glass window, yet they also call to mind Matisse&#x2019;s painting.', 1688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1689, 'Caulfield had several favourite subjects, among them the lamp and the vase.', 1689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1690, 'He made many small paintings each around 50 cm high of one or two items, as well as many of entire interiors on a larger scale usually 2 metres high or more.', 1690, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1691, 'His paintings can be seventeenth century Dutch interiors and still lifes; he painted the aspirations of an equivalent social group in his own day.', 1691, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1692, 'Caulfield&#x2019;s best known works are some of the simple still lifes, for example a single lamp, a goldfish in a bowl, an ashtray with a cigarette, a vase, an oval mirror which somehow conveys the idea that it is reflective even though it is painted in black and white.', 1692, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1693, 'The schematic, iconographic way these things are painted makes them deceptively simple to look at.', 1693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1694, 'Of his larger works, perhaps the interiors of a Swiss bar, is the best known.', 1694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1695, 'This interior is painted mainly in blue (with the usual black outline), which signifies the quality of light in the place rather than the materials of which the furniture is made.', 1695, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1696, 'In this work Caulfield uses trompe l&#x2019;oeil, another characteristic technique: the photo mural on the wall behind the banquette seating is painted realistically in that it looks like a view of an actual mountain scenery rather than a schematic representation.', 1696, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1697, 'Another example in which Caulfield paints a piece of wood grain realistically makes the direct acknowledgment of Braque&#x2019;s work more explicit.', 1697, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1698, 'Caulfield never painted a person.', 1698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1699, 'Richard Hamilton', 1699, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1700, 'Hamilton is another well known British pop artist who made paintings that are figurative and usually have a realistically painted element to them, perhaps a figure, combined with an abstract, more painterly element.', 1700, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1701, 'Parts of the paintings are often blurry and watery, painted on un primed or thinly primed canvas.', 1701, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1702, 'Like many of the pop artists, Hamilton used the techniques of graphic art, such as air brushing and photographic reproduction, in combination with oil painting.', 1702, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1703, 'This can be seen in the painting of the IRA hunger striker Bobby Sands during the period of his dirty protest made in the 1970s which shows the long haired, bearded Sands in his prison cell in front of a wall smeared with his own excrement.', 1703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1704, 'Hamilton used an airbrush to paint the excrement as blurry brown squiggles.', 1704, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1705, 'Hamilton&#x2019;s collages are made as sketches for paintings but sometimes are presented as works in their own right, such as Hamilton&#x2019;s arguably best known work, A Plan for Everyday Living.', 1705, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1706, 'This shows a montage of a modern domestic interior, an apartment with cantilevered stairs descending into a double height living area with picture windows that are being vacuumed by a body builder dressed only in a frilly apron.', 1706, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1707, 'Eduardo Paolozzi', 1707, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1708, 'Paolozzi is a British artist who made works on paper and sculpture that could be considered as pop art.', 1708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1709, 'Paolozzi specialised in patterns based on a grid of small coloured squares, which are complex and highly decorative, referring both to historical architectural decoration and textile design as well as to 1960s graphic style.', 1709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1710, 'He used the same patterning to create cast metal sculptures, often made from aluminium.', 1710, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1711, 'In the 1980s Paolozzi was commissioned to design the mosaic tiling for the walls of Tottenham Court Road underground station in London.', 1711, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1712, 'This commission made Paolozzi&#x2019;s work one of the most frequently encountered public art commissions in the world.', 1712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1713, 'Peter Blake', 1713, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1714, 'British pop artist who is known best for his the sleeve design of the Beatle&#x2019;s Sergeant Pepper album.', 1714, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1715, 'Blake&#x2019;s paintings are dense, detailed figurative collage style works.', 1715, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1716, 'They often contain elements of patterning, decorative borders and are meticulously painted.', 1716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1717, 'He often chose to portray British national identity in some way.', 1717, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1718, 'He included a self portrait in many paintings &#x2013; he always appears with long hair and a long beard.', 1718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1719, 'Jim Dine', 1719, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1720, 'A contemporary of Rauschenberg and Johns in New York in the 1960s, Dine&apos;s best known work features his trademark hearts, drawn in outline or painted often in red or pink on white.', 1720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1721, 'Robert Longo', 1721, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1722, 'Longo is an American artist who made paintings, drawings and sculptures in the 1970s and 80s.', 1722, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1723, 'The sculptures are usually complementary to, or even shown as a part of a painted work.', 1723, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1724, 'Longo made a number of works in two and a half metre high panels arranged in threes and fours, one panel showing a man clothed in a suit apparently falling to the ground (perhaps having been shot), although he could almost be dancing, the other panels blank white or with photographic cityscapes.', 1724, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1725, 'The pencil and graphite drawing on the panels is very realistic.', 1725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1726, 'In some cases there is a bronze cast of a similar male figure placed in front of the wall panels, the best known being of a man &#x2018;falling&#x2019;, the balance of the sculpture precarious.', 1726, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1727, 'Robert Indiana', 1727, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1728, 'A screen print and sculpture made by Indiana became the motif for a generation.', 1728, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1729, 'He placed the letters of the word &#x2018;love&#x2019; one on top of the other to form a cube shape with a distinctive slanted letter &#x2018;O&#x2019;.', 1729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1730, 'Pop art was a major movement in twentieth century modern art.', 1730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1731, 'Conceptual art had been developing from its roots in dada and surrealism, notably in the work of European artists who had been influenced by these movements such as Klein and Broodthaers.', 1731, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1732, 'Yves Klein', 1732, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1733, 'Although he cannot be classed purely as a conceptual artist, French artist Klein&#x2019;s subject was the condition of art, and he made several works that gained him notoriety, in particular the Blue Paintings.', 1733, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1734, 'These were made as a performance in a gallery in Paris.', 1734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1735, 'Klein invited female models to act as human brushes.', 1735, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1736, 'He applied ultramarine blue paint to their naked bodies and then directed them to position themselves and move their bodies in certain ways, making body prints onto paper he had placed on the floor and walls.', 1736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1737, 'Klein&#x2019;s idea was to use the nude to paint the nude.', 1737, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1738, 'The resulting body prints were exhibited, but it is the photographic documentation of the event that has become better known.', 1738, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1739, 'Later on he made some paintings by setting fire to canvases, singeing them and marking them with smoke.', 1739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1740, 'Ultramarine blue was Klein&#x2019;s trademark colour that he used for all of his painted work and sculpture.', 1740, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1741, 'He made a large number of paintings in the 1950s and early 60s using natural sponges stuck to canvas and painted blue.', 1741, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1742, 'He also made simple plain blue canvases.', 1742, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1743, 'Similarly he made sculptures with the sponges, creating tableaux of his flower or seaweed like creations.', 1743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1744, 'Klein worked briefly in ceramics, making small sculptures that drew on porcelain table ornaments, lumpen thrown together and glazed versions that nevertheless made their sources clear.', 1744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1745, 'The other strand to Klein&#x2019;s work is more conceptual.', 1745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1746, 'He made many works with found objects and works that were events and documentations of actions.', 1746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1747, 'He made a work with a light bulb and several works with furniture.', 1747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1748, 'The best known of these works is Leap into the Void, a staged photograph in which Klein is seen apparently leaping off a high wall in a street and falling through the air.', 1748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1749, 'There is a house on the left and a lamp post behind him.', 1749, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1750, 'Paris Air is a sealed glass vial containing nothing but air, to which Klein accorded a status as an artwork and a monetary value.', 1750, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1751, 'In a performance work Klein sold gold leaf which he had authenticated to collectors and then invited them to throw the work they had just bought into the river Seine.', 1751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1752, 'He also printed his own bonds, and sold these as works of art.', 1752, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1753, 'The work that summed up Klein&#x2019;s interests most completely was The Void, a staged event for which Klein rented an empty gallery.', 1753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1754, 'He sent out invitations to the opening of his exhibition, provided champagne and hired a commissionaire to stand on the door.', 1754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1755, 'No one was allowed to enter the gallery without an invitation and when they did so they found an empty gallery &#x2013; the void of the title.', 1755, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1756, 'Marcel Broodthaers', 1756, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1757, 'Like Klein, the Belgian artist Marcel Broodthaers cannot be defined as a conceptual artist but he draws both from this and surrealism.', 1757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1758, 'Broodthaers occupies an eccentric personal world that centres around his Mus&#xe9;e des Aigles, and the mussel shell.', 1758, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1759, 'Broodthaers was something of a surrealist, with his use of puns and irony, and juxtaposition of unlikely objects.', 1759, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1760, 'He created his own, sometimes impenetrable, lexicon of signs and symbols, and indeed signs were part of his work.', 1760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1761, 'He made pressed sheet metal signs displaying diagrammatic objects such as a pipe, with &#x2018;fig 1&#x2019; and &#x2018;fig 2&#x2019; written underneath.', 1761, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1762, 'He made a number of small sculptures and wall reliefs using mussel shells stuck together.', 1762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1763, 'The Mus&#xe9;e des Aigles (Museum of Eagles) contained things that the artist had collected which bore eagles&apos; wings, such as military crests.', 1763, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1764, 'CONCEPTUAL ART', 1764, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1765, 'Hans Haacke', 1765, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1766, 'American Haacke became one of the best known of the 1970s&#x2019; conceptual artists in America and Europe.', 1766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1767, 'His practise was political in the sense that his subject matter was a critique of multinational corporations and advertising.', 1767, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1768, 'Haacke made a number of installations consisting of text panels with photographs detailing the activities of multinational companies such as William Morris, often subverting advertising design used by the company.', 1768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1769, 'Haacke&apos;s earlier sculptural work includes a piece called Condensation Cube (1965), a Plexiglas cube about 50 cm square with naturally occurring and accumulating droplets of condensation inside it.', 1769, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1770, 'Alighiero Boetti', 1770, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1771, 'The Italian artist Boetti made quite a lot of wall hangings using embroidery, chiefly maps of the world, but also tapestry panels showing the letters of the alphabet.', 1771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1772, 'His interests were naming, writing and maps.', 1772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1773, 'He often made work using embroidery and tapestry, as well as the equally time consuming method of using a ballpoint pen to colour large areas.', 1773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1774, 'Boetti made a series of drawings in ballpoint pen of invisible words.', 1774, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1775, 'Reading from a key to the drawing along the top and sides, it is possible to discern words hidden in the drawings by referring to inverted commas on a grid.', 1775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1776, 'The whole paper is coloured by intensive use of the blue or red ballpoint, leaving only the inverted commas white.', 1776, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1777, 'On Kawara', 1777, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1778, 'A Japanese artist who began working in the 1960s, Kawara is known for a number of conceptual projects and endurance works.', 1778, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1779, 'I Met, I Went is a year of postcards written and mailed to friends and acquaintances by Kawara every day for a year.', 1779, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1780, 'The work with which Kawara is usually associated is a constantly accumulating series called the Date Paintings, of which he has made one a day since the 1960s.', 1780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1781, 'Each identical 50 cm high painting has the day&#x2019;s date painted in white numerals on a black canvas.', 1781, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1782, 'Michael Craig Martin', 1782, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1783, 'Craig Martin is British American artist born in the 1940s who makes wall paintings depicting ordinary objects &#x2013; furniture, paperclips, tools, bicycles, lamps, globes and fittings are juxtaposed without reference to relative scale at various angles.', 1783, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1784, 'The objects are placed on very brightly coloured grounds painted with matt emulsion paint and outlined in black plastic tape, except for a period in the 1980s when Craig Martin used square sectioned steel rods bent to shape and welded to create the outlines.', 1784, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1785, 'The wall paintings may fill a whole gallery or museum, or just one wall.', 1785, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1786, 'Craig Martin&#x2019;s earlier work made in the 1960s and 70s is conceptual.', 1786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1787, 'His best known work is the Oak Tree, which consists of a glass of water placed on a glass shelf above the viewer&#x2019;s head and an accompanying framed text which explains to the viewer why the glass of water is an oak tree, by means of a question and answer between the artist and a fictitious interlocutor.', 1787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1788, 'The artist claims that it is by the authority invested in him as an artist that the glass of water is an oak tree, thus this is a work about authorship and subjectivity.', 1788, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1789, 'He also made a work with a row of clipboards and plumb lines hung on a wall, a series of boxes with hinged lids placed on the floor, the lids taking progressively larger parts of the box until the lid was more box and the box was more lid.', 1789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1790, 'Sol Le Witt', 1790, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1791, 'An American conceptual artist who made installation and drawings, Le Witt is best known for his wall drawings made in pencil directly onto the wall which is painted either black or white.', 1791, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1792, 'He devised complex geometric patterns of lines &#x2013; parallel, radiating or on a grid &#x2013; which are drawn in coloured pencil, forming a barely perceptible drawing which nevertheless has a strong effect on the space and adds glowing areas of colour.', 1792, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1793, 'Le Witt also made a number of sculptures based on the grid.', 1793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1794, 'These are three dimensional grids formed from 30 cm cubes stacked in rows on the floor.', 1794, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1795, 'the whole sprayed with white lacquer.', 1795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1796, 'Each layer has a different formation and may be up to 40 cubes long.', 1796, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1797, 'The cubes are not solid, so that the structure has a complex appearance.', 1797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1798, 'Daniel Buren', 1798, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1799, 'Buren painted lozenge shapes on buildings and architectural structures, making site specific works that use the lozenge shapes as a visual intervention to prompt a reconsideration of the scene presented to the viewer, and attempt to alter the reading of the picture plane, treating an environment as if it were no more than a photograph.', 1799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1800, 'The lozenges allude to signage and logos are entirely without function.', 1800, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1801, 'Buren&apos;s work is as much to do with reconsidering landscape painting as it is do with installation.', 1801, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1802, 'Victor Burgin', 1802, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1803, 'An American artist who made conceptual work from the 1960s onwards with a strong theoretical slant which is evident both in the work and in his writing about art.', 1803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1804, 'James Lee Byars', 1804, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1805, 'One of Byars&#x2019;s sculptures is a clear acrylic case, containing white sand, a white book, and a cream coloured (almost white) snake.', 1805, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1806, 'This work can be recreated anywhere as long as the artist&#x2019;s instructions are followed: he specifies the white sand, the dimensions of case and book, which must be made by a bookbinder, and that the snake must be as close to white as is available.', 1806, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1807, 'Early conceptualism implied a form of resistance to subversion of the cultural norm.', 1807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1808, 'This gave the work of these artists a political edge until at the end of the twentieth century conceptualism became the norm.', 1808, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1809, 'One artist who is identified with a subversive intention is Beuys, who made conceptual and political art between the 1950s and the 80s.', 1809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1810, 'Joseph Beuys', 1810, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1811, 'Born in early 1930s Beuys is one of the most significant German artists of the second half to the twentieth century.', 1811, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1812, 'He was a professor at the Dusseldorf academy for many years, where he had a huge influence on several generations of younger artists.', 1812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1813, 'Beuys was an eccentric character who always dressed in the same canvas hat and black canvas shooting waistcoat with multiple pockets.', 1813, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1814, 'He was extremely prolific, working in all media but chiefly known as a sculptor, performance and installation artist who proclaimed that &#x2018;life is art&#x2019;, thus making his every action a part of his work.', 1814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1815, 'Beuys is notorious for the myth of a near death experience that surrounds him and although long since discredited has proved impossible to ignore.', 1815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1816, 'It was said that he had been shot down when flying for the Luftwaffe in the second world war over snowy mountains.', 1816, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1817, 'His life was saved by local villagers who found him and kept his body temperature up by smearing him in pig fat and wrapping him in felt.', 1817, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1818, 'Whether apocryphal or not, this event would seem to have had a profound influence on most of Beuys&#x2019;s work, given that his favoured materials are felt and fat.', 1818, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1819, 'However, Beuys&#x2019;s personal lexicon is often impenetrable and inaccessible.', 1819, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1820, 'One of his best known works is Portrait of the Artist Talking to a Dead Hare, which was made for his first solo show in New York in 1979.', 1820, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1821, 'Beuys sat in the gallery, his head covered in honey and gold leaf (also highly important symbolic substances in his work), cradling a dead hare in his arms and talking to it.', 1821, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1822, 'As a declared socialist and an anti capitalist, politics are a major feature of Beuys&#x2019;s work.', 1822, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1823, 'He was sacked from his academic post at Dusseldorf for inciting student riots, although the exact truth is subject to speculation.', 1823, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1824, 'In his second New York show he made a work with a live wolf, titled I Like America and America Likes Me.', 1824, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1825, 'Beuys sat in the gallery behind a chain link fence separating him and the viewer, talking to the wolf for a week.', 1825, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1826, 'The wolf symbolised the plundering and appropriation of the American wilderness and by his interaction with its spirit Beuys was trying to heal the wounds caused to the indigenous people.', 1826, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1827, 'Beuys&#x2019;s best known work is Fat Chair, a wooden chair with lard piled at a slant towards the back of it.', 1827, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1828, 'He made a number of works from stacks of plate steel and felt which he described as batteries, a kind of life preserving power source.', 1828, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1829, 'A number of vitrines containing an array of mysterious but apparently utilitarian metal, wood, fat and felt objects.', 1829, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1830, 'A series of performances given by Beuys took the format of lectures often conducted in a studio, in which he used blackboards to illustrate a talk, usually about the possibility of art being life, and in particular to make his famous claim that &#x2018;Art is a Social Sculpture&#x2019;.', 1830, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1831, 'By this he meant that art could not exist without the interaction of the viewer, it was therefore subjective, and thus a social event and by extension political.', 1831, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1832, 'The blackboards with their drawings, diagrams and writings remain as a document of the lecture.', 1832, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1833, 'Beuys made himself a felt suit and various other garments and items, which usually had a cross cut from cotton fabric stitched onto them.', 1833, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1834, 'In 1985 Beuys installed rolls of felt the height of a London gallery all round the walls and across the entrance, leaving only a small three foot high gap from the floor up for the viewer to enter.', 1834, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1835, 'Inside was a grand piano.', 1835, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1836, 'A total damped silence was implied by felt and experienced by the deadened acoustic.', 1836, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1837, 'Beuys also made a work consisting of a Volkswagen camper van with a number of wooden sledges emerging from its door, linked by a harness.', 1837, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1838, 'Public works consisted of the planting of 5000 trees in a small town and the casting of a concrete public underpass by pouring melted lard into it and then cutting it out.', 1838, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1839, 'Beuys made many works on paper, using charcoal, paint, ink and, in particular, a specific brand of rust coloured paint, the kind used to preserve sail cloth or paint door steps.', 1839, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1840, 'The name of the paint and the colour was personally symbolic.', 1840, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1841, 'In the first half of the century some artists were involved more directly in politics.', 1841, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1842, 'ART AND POLITICS', 1842, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1843, 'Artists have often used their skills in the service of their political beliefs, sometimes by working as official state artists, in which case they were well provided for.', 1843, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1844, 'The Soviet government used socialist realist art as a propaganda tool and so artists who wanted to resist found other ways of working.', 1844, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1845, 'Chinese state artists were similarly employed, some even worked at altering photographs to suit the government&#x2019;s needs.', 1845, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1846, 'Artists working under totalitarian regimes who had opposing political beliefs may have had no choice but to serve the state or risk punishment.', 1846, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1847, 'In order to avoid this many defected or worked underground and in these situations art has often been a tool of resistance or subversion.', 1847, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1848, 'Most of these artists did not achieve great fame due to the circumstances in which they had to live, but some did.', 1848, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1849, 'Picasso&#x2019;s Guernica is a well known work of political resistance.', 1849, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1850, 'Some artists simply used their skills to record what they found abhorrent.', 1850, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1851, 'Kathe Kollwitz', 1851, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1852, 'Kollwitz is an Austrian artist who made contemporaneous drawings in the concentration camps during the holocaust mainly in graphite and charcoal often depicting women.', 1852, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1853, 'Diego Rivera', 1853, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1854, 'Rivera was a Mexican mural painter working in the 1930s and 40s who made political wall paintings celebrating ordinary people and workers in public buildings in the service of the socialists.', 1854, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1855, 'He fell out of favour when the socialist government gave way to a right wing party who found him politically embarrassing and prevented him from finishing his last major public commission.', 1855, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1856, 'Rivera was the husband of the artist Frida Kahlo and a friend of Leon Trotsky.', 1856, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1857, 'The posters used by the demonstrators in the national strike and demonstrations in Paris and other cities in May 1968 borrowed the ideas of the Situationist International group of artists, who set up a poster printing workshop to make them.', 1857, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1858, 'These bold graphic one colour screen prints had simple images and texts, for example &#x2018;Under the pavement is the Beach&#x2019; and &#x2018;Beauty is in the streets&#x2019;.', 1858, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1859, 'THE SITUATIONIST INTERNATIONAL', 1859, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1860, 'Guy Debord', 1860, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1861, 'Founder of the Situationist International, a Paris based group of international artists, Debord led the group with his revolutionary ideas (and politics).', 1861, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1862, 'Debord took Baudelaire&apos;s idea of the flaneur, the wanderer through a city, and developed it into his personal concept of the &#x2018;d&#xe9;rive&#x2019;, a directed walk through urban scenery.', 1862, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1863, 'Debord believed that people should interact with their city, to which end he had various ideas including putting light switches on street lamps so that the people could turn them on and off at will.', 1863, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1864, 'Asger Jorn', 1864, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1865, 'A Dutch artist and member of the Situationists, Jorn made collages with torn posters, for example a sixteenth century portrait of a woman in a blue brocade dress has her face defaced by the additions of paint and a collaged element.', 1865, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1866, 'There was a strong performative element in what the Situationists proposed.', 1866, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1867, 'Many artists in the 70s took conceptual objections to the status of the art object to its logical extreme and began to make performance art, dispensing with the object and any sense of permanence entirely, using their own bodies as both subject and material.', 1867, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1868, 'Performance art was also a focus for many women artists who saw it as a way to make work about reclaiming of the female body by women.', 1868, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1869, 'PERFORMANCE ART', 1869, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1870, 'Carolee Schneeman', 1870, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1871, 'American artist Schneeman&#x2019;s best known work is Meatjoy (1975), for which a large number of naked performers were instructed to perform an orgiastic celebration by wallowing in animal entrails and pieces of meat and blood.', 1871, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1872, 'EyeBody was a solo work by Schneeman in which she sat on a swing, naked, in a space with white backdrop paper on the walls, holding an umbrella.', 1872, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1873, 'During the performance she made a drawing by swinging as close as she could to the walls and drawing on them.', 1873, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1874, 'For another work Interior Scroll, Schneeman read out loud a poem that she had written, from a long strip of paper previously inserted into her vagina and gradually extracted as she read.', 1874, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1875, 'Schneeman&#x2019;s Olympia, made in collaboration with sculptor Robert Morris, was a performance in which she posed as the woman in Manet&apos;s eponymous painting.', 1875, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1876, 'Morris, dressed in a white robe and wearing leather work gloves, carried large plywood boards around, arranging them as a backdrop to Schneeman.', 1876, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1877, 'Both performers wore white makeup.', 1877, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1878, 'The piece was concerned with the &#x2018;work&#x2019; of art, about the male artist and the female model, and about the translation from two to three dimensions, the boards representing &#x2018;planes&#x2019;.', 1878, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1879, 'Tseching Hsieh', 1879, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1880, 'This Chinese artist made a performance in the early 1980s for which he was tied to another person by a rope 3 metres long for one year.', 1880, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1881, 'Allan Kaprow', 1881, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1882, 'Kaprow is best known for his Happenings in New York in the late 1960s.', 1882, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1883, 'These were site specific installations in which a performance would happen witnessed by an invited audience.', 1883, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1884, 'The Happenings were one of the earliest examples of artists making live art in galleries or gallery like spaces rather than in a theatre or studio space.', 1884, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1885, 'One Happening took place in a loft in which a structure of stud wall frames covered with transparent plastic sheeting created a box like space in which the performers could be seen but were obscured.', 1885, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1886, 'Kaprow wrote a seminal book about the Happenings which was influential for artists making time based work.', 1886, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1887, 'Eleanor Antin', 1887, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1888, 'Antin is an American artist best known for her work Carving: a Traditional Sculpture made in 1971, for which she put herself on a strict diet and had a male doctor weigh and measure her every day for a month.', 1888, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1889, 'This is one of a number of works in which Antin investigated the effect of the ideals forced upon women in a patriarchal society.', 1889, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1890, 'In this work she attempted to literally sculpt her own body, making a comment both on women&#x2019;s control over their own bodies, on the centuries of depiction of the nude female body by men, and on women&#x2019;s continuing need to make themselves attractive for men.', 1890, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1891, 'The performance was documented by one photograph every day that were then placed together in a grid and framed, and by a video.', 1891, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1892, 'During the 1980s Antin began to make more theatrical performances, using cut out puppets.', 1892, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1893, 'She also developed an alter ego, Eleanora Antinova, a trans gender Russian ballet dancer who appeared in a tutu and a long beard.', 1893, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1894, 'Marina Abramovic and Ulay', 1894, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1895, 'Abramovic first came to public attention when she invited visitors to a gallery in which she appeared naked, stating that the visitors could do anything they wanted to her and she would not resist or retaliate.', 1895, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1896, 'She provided a number of implements with which to do this including knives and a gun.', 1896, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1897, 'Abramovic narrowly avoided serious injury but discovered that her initial premise was correct: like the invisible barrier of etiquette surrounding an artwork, there was a barrier of propriety and embarrassment protecting her that was only broached when the beginnings of a mob mentality formed.', 1897, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1898, 'Abramovic worked together with her partner Ulay until the early 1980s making performance &#x2018;sculptures&#x2019; and endurance works.', 1898, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1899, 'A work entitled Breathe linked them in a mouth to mouth embrace for as long as they could breathe using their combined exhaled breath.', 1899, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1900, 'They braided their hair together and stayed sitting back to back for eight hours.', 1900, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1901, 'For another work they used a full size bow and arrow and stood facing each other, with Ulay holding the string and Abramovic holding the arrow at the point on the centre of the bow string from which it is released.', 1901, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1902, 'They maintained this state of equilibrium through tension until the strain of holding on meant they had to either stop or let go of the tension in the bow.', 1902, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1903, 'This would have resulted in the release of the arrow, which was aimed at Abramovic.', 1903, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1904, 'In Doorway they stood naked and facing each other on either side of the entrance to the gallery.', 1904, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1905, 'This meant that those wishing to enter were forced to brush past them and had to choose who to face as they turned sideways to enter.', 1905, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1906, 'These partner works focused on endurance through concentration and on the tension in partnerships manifested in physical mutual support.', 1906, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1907, 'They are notable for the degree of politeness and gentleness combined with a power and implicit violence.', 1907, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1908, 'The artists described them as sculptures.', 1908, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1909, 'After the relationship with Ulay ended Abramovic continued to make endurance works.', 1909, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1910, 'While these maintained a formal sculptural quality they also acquired a ritual aspect, as in the work in which she sat in a circle of salt surrounded by poisonous snakes.', 1910, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1911, 'In another work created in an amethyst mining town in Brazil, she made and wore clogs from blocks of amethyst.', 1911, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1912, 'Abramovic made a work for a tree sited in a public square in which she placed a number of speakers playing birdsongs so that it seemed that the tree was teeming with tiny birds.', 1912, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1913, 'Vito Acconci', 1913, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1914, 'Acconci, an American artist, made several endurance works in the early 1970s, notably Seedbed, for which he built a false gallery floor which sloped up from the door to the rear of the space.', 1914, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1915, 'Acconci was reputedly sealed in the void under the floor masturbating.', 1915, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1916, 'In another work he constructed a shelf high up on the gallery wall in such a way that he could not be seen by those in the gallery from any angle and stayed on the shelf for the hours during which the gallery was open.', 1916, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1917, 'In these works he made the gallery space and the viewer&#x2019;s own feelings about being in that space into the subject of the work.', 1917, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1918, 'A smaller scale work involved a video on a monitor placed on a furry rug on the floor.', 1918, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1919, 'On the screen Acconci is seen, lying on his stomach, his face right up against the camera, talking to the viewer and inviting them to lie down on the rug and join him on the floor.', 1919, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1920, 'Chris Burden', 1920, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1921, 'Burden became known in the late 1960s and early 70s for his performance work that mostly involved physical endurance.', 1921, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1922, 'In &#x2018;Shoot&#x2019; he arranged for a friend to shoot him in the arm in a gallery at a specified time in front of an audience.', 1922, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1923, 'The shooting, which did not seriously injure Burden, was documented and like all his works of the period, the documentation became the work.', 1923, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1924, 'In Locker Piece he had himself locked in a left luggage locker at a railway station for eight hours.', 1924, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1925, 'In Freeway he lay in the middle of a freeway.', 1925, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1926, 'He also had himself nailed to the bonnet of a Volkswagen Beetle through his hands and feet.', 1926, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1927, 'Burden was interested in making formal sculptural work using his own body and in the visual power of pain and danger.', 1927, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1928, 'The purity and simplicity of the works made them very powerful.', 1928, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1929, 'In his later work he developed an interest in war and military capability through his pacifist beliefs and interest in ecology and the environment.', 1929, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1930, 'He made a work involving hundreds of tiny model submarines, and a large meteorite like lump suspended from the gallery ceiling with model railway track running all over it and in and out of it.', 1930, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1931, 'In 1999 Burden constructed a large and complex computer controlled machine for making and throwing paper aeroplanes.', 1931, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1932, 'Joan Jonas', 1932, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1933, 'An American performance artist and musician who worked with Judson Church dancers Yvonne Rainer and Merce Cunningham, Jonas made a performance work in which she played the cello.', 1933, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1934, 'Dara Birnbaum', 1934, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1935, 'Birnbaum is an American artist best known for her performance in which she dressed as Wonder Woman.', 1935, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1936, 'Some women artists made work that although not performed was performative in its intention.', 1936, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1937, 'They included Judy Chicago and Mary Kelly.', 1937, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1938, 'Judy Chicago', 1938, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1939, 'American artist Chicago changed her name from the patronymic to that of her birthplace as a feminist gesture in the 1970s.', 1939, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1940, 'Chicago&#x2019;s work The Dinner Party from 1972 became an iconic feminist work.', 1940, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1941, 'It is a narrow table arranged in a triangular format, with place settings for all the famous and unsung heroines of American life, for example Mrs Lincoln.', 1941, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1942, 'The place settings are actually embroideries depicting plates, each one made by a different woman artist, similar to the way women make church kneelers.', 1942, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1943, 'Chicago wanted to draw attention to the under representation of women&#x2019;s achievement by staging this imaginary dinner party of these great women, using traditionally female but culturally undervalued materials and methods.', 1943, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1944, 'She brought the women together by means of the dinner table because this is how women had traditionally brought people together.', 1944, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1945, 'The work came to be seen as representative of the struggle for recognition of women from all areas of life and times, and was influential for several succeeding generations of artists.', 1945, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1946, 'Mary Kelly', 1946, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1947, 'An American artist who made works dealing with feminist issues from the 1970s onwards.', 1947, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1948, 'Kelly&#x2019;s seminal work is the Post Partum Document, an extremely influential work made in 1973 documenting the birth and emergence into language of her son Kelly.', 1948, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1949, 'The work takes the form of about thirty framed panels, each containing an object and a text.', 1949, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1950, 'The object might be a soiled nappy (which helped to gather tabloid attention at the time), or an item of clothing.', 1950, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1951, 'The text details the child&#x2019;s weight and length, age in weeks, and describes his development with notes on his linguistic development.', 1951, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1952, 'In this work Kelly documents not only the birth of her child but also her care for his life as a creative activity.', 1952, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1953, 'This startlingly simple and obvious statement caused a great deal of criticism and publicity, and the Post Partum Document was declared not to be art, to be offensive and even cruel.', 1953, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1954, 'Despite the criticism Kelly was widely acknowledged to have raised the issue of motherhood as a taboo, as work that is not to be considered work, not on a par with artistic achievement and not to be revealed in all its messy detail.', 1954, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1955, 'The work&#x2019;s form was important.', 1955, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1956, 'It was predominantly a text work and this was another of Kelly&#x2019;s points &#x2013; that text, or language, is how the subject is constituted and that we are not subjects until we are speaking subjects.', 1956, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1957, 'The emergence of a child into language is therefore the most important moment in our existence.', 1957, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1958, 'Kelly drew on the works of Lacan, the French literary theorist who developed the theory of the other and the difference between the male and female subject, and of psychoanalytic writers such as Freud and Klein.', 1958, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1959, 'Lacan&apos;s theories on the constitution of the subject were particularly influential for a whole generation of artists in the 1980s, mostly but not all of them women.', 1959, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1960, 'Kelly&#x2019;s later work developed into institutional critique and was always wall and text based.', 1960, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1961, 'She made a work that consisted of highly crafted metal medallions or wall plaques.', 1961, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1962, 'Hannah Darboven', 1962, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1963, 'Artist working in the 1960s and 70s who made works using text.', 1963, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1964, 'Darboven was interested in catalogues, indexes and diaries, one work for example took hundreds of index cards on which the artist had written and displayed them carefully categorised.', 1964, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1965, 'The text on the cards however consisted only of &#x2018;x&#x2019;s.', 1965, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1966, 'This display of an organising system that contained no information served to visualise a practice which is in use in daily life, but which is never actually seen and rarely considered.', 1966, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1967, 'Darboven&#x2019;s obsessive writing projects are always made by hand.', 1967, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1968, 'Hannah Wilke', 1968, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1969, 'American artist who became known in the 1970s for her photographic and performance work.', 1969, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1970, 'Wilke often appeared naked, which was controversial at a time when feminist artists were reclaiming the female body, traditionally painted naked by men, for themselves.', 1970, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1971, 'For one performance she appeared naked but wearing high heeled shoes on the steps of a public building.', 1971, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1972, 'Wilke&#x2019;s Chewing Gum Scarification Series is her best known work, in which she applied a large number of &#x2018;scars&#x2019; made from chewed gum to her naked torso and photographed herself.', 1972, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1973, 'These scars were also exhibited as sculptures.', 1973, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1974, 'Wilke made a video work which shows her in her apartment, mostly on the phone to a man with whom it seems evident she is flirting.', 1974, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1975, 'The film is a study in body language and how the viewer interprets it.', 1975, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1976, 'Martha Rosler', 1976, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1977, 'American artist who began her career in the seventies making a number of photographic and text based works which juxtapose text and image to make work that highlights social inequity and challenges assumptions.', 1977, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1978, 'She is best known for her seminal work the Bowery Project.', 1978, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1979, 'This consists of a series of photographs paired with texts that juxtapose words or phrases used to describe people who live on the streets with images of the area in which they live.', 1979, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1980, 'An image of a banking hall doorway, for example, is paired with the phrase &#x2018;down and out&#x2019;.', 1980, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1981, 'An early collaborative work called Metal Box Factory is a systematic survey of a number of employees in a factory around 1970.', 1981, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1982, 'Rosler asked the workers to write down their daily schedules both at work and home, displayed the results and made a comparison of the time spent working and at home.', 1982, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1983, 'The schedules reveal the amount of work done in the home mostly by the women to be almost as much as the work done in the factory.', 1983, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1984, 'Clocking on cards and production line rotas are also part of the display of material in the installation.', 1984, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1985, 'Rosler made a series of collages showing domestic interiors that are (often humorous) comments on the division of labour in the home and the role of the housewife.', 1985, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1986, 'Rosler is one to the earliest artists to make politicised feminist work which presented a critique of society.', 1986, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1987, 'Performance art often combined video and installation.', 1987, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1988, 'Some artists like Bruce Nauman had a multi disciplinary practice.', 1988, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1989, 'Bruce Nauman', 1989, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1990, 'Nauman is an American artist who began his career in the 1960s making performance, installation, sculpture and video work.', 1990, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1991, 'In fact Nauman made some of the earliest video art, in the days when the technology was new and only television broadcast equipment was available.', 1991, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1992, 'This was bulky and heavy, and editing equipment was not readily available.', 1992, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1993, 'Nauman was also one of the first artists to consider the television monitor as an art object in itself, as seen in his corridor installation.', 1993, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1994, 'This consists of two 4 metre high freestanding white walls, placed next to each other with a gap in between.', 1994, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1995, 'The walls are at a slight angle so that the gap between them narrows gradually until it is the width of a monitor, which shows only white interference.', 1995, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1996, 'As the viewer approaches the work from the wider end, the light from the monitor creates a hypnotic effect so that the viewers feel compelled to enter the corridor and walk as far as they can before they no longer fit the space.', 1996, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1997, 'This is intended to represent the tunnel with a white light at the end that is often described by those who have had a near death experience.', 1997, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1998, 'In the 1960s and 70s, Nauman made several performed works that are usually viewed as video documents.', 1998, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1999, 'The most well known is Taking a Line for a Walk, in which Nauman is seen walking around a square marked on the floor.', 1999, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2000, 'Another work, a development of this piece, is a 4 metre high white box round which the viewer can walk.', 2000, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2001, 'A closed circuit television monitor is placed at each corner, on which the viewer sees himself or herself passing the previous monitor.', 2001, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2002, 'The film playing on the monitor is played back at slight delay, so that the viewers are following themselves.', 2002, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2003, 'At the same time, since they are walking around a square, the implication is that they ought to be able to catch up with themselves.', 2003, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2004, 'Nauman made other video works, one for example in which he is dressed as a clown and laughs uncontrollably for thirty minutes.', 2004, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2005, 'The way the video is presented is always important; in this the monitor is in a wooden cubicle.', 2005, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2006, 'In the 1980s Nauman began to make more static sculptural work, and began a series in which he cast dogs in rubber and displayed them in various ways, for example hanging them from the ceiling in a carousel like structure.', 2006, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2007, 'In the 1990s Nauman made a large scale video installation for which he filmed himself, head and shoulders, talking to himself, and presented a number of these films on 2 metre high flat screen monitors placed upside down.', 2007, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2008, 'Cinema and the work of experimental filmmakers had a great influence on many artists and with the advent of early video technology the distinction between art and film became blurred.', 2008, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2009, 'Nam June Paik', 2009, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2010, 'This American artist was one of the first to make and show video as a sculpture.', 2010, 1, '1.1', 0);
